import java.util.HashMap;
import java.util.HashSet;
import java.util.Set;

public class Solution {
    /**
     * Given an n x n binary matrix grid. You are allowed to change at most one 0 to be 1.
     * Return the size of the largest island in grid after applying this operation.
     * An island is a 4-directionally connected group of 1s.
     *
     * @param grid The input binary matrix.
     * @return The size of the largest island after applying the operation.
     */
    public int largestIsland(int[][] grid) {
        int n = grid.length;
        int islandId = 2;
        HashMap<Integer, Integer> islandSize = new HashMap<>();
        int maxIslandSize = 0;

        // Find all islands and calculate their sizes
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    int size = dfs(grid, i, j, islandId);
                    islandSize.put(islandId, size);
                    maxIslandSize = Math.max(maxIslandSize, size);
                    islandId++;
                }
            }
        }

        // Try changing each 0 to 1 and calculate the resulting island size
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 0) {
                    Set<Integer> neighbors = new HashSet<>();
                    if (i > 0) neighbors.add(grid[i - 1][j]);
                    if (i < n - 1) neighbors.add(grid[i + 1][j]);
                    if (j > 0) neighbors.add(grid[i][j - 1]);
                    if (j < n - 1) neighbors.add(grid[i][j + 1]);

                    int newIslandSize = 1;
                    for (int neighbor : neighbors) {
                        if (neighbor > 1) {
                            newIslandSize += islandSize.get(neighbor);
                        }
                    }
                    maxIslandSize = Math.max(maxIslandSize, newIslandSize);
                }
            }
        }

        return maxIslandSize;
    }

    private int dfs(int[][] grid, int i, int j, int islandId) {
        int n = grid.length;
        if (i < 0 || i >= n || j < 0 || j >= n || grid[i][j] != 1) {
            return 0;
        }

        grid[i][j] = islandId;
        return 1 + dfs(grid, i + 1, j, islandId) +
                dfs(grid, i - 1, j, islandId) +
                dfs(grid, i, j + 1, islandId) +
                dfs(grid, i, j - 1, islandId);
    }
}

