public class Solution {
    public int robotSim(int[] commands, int[][] obstacles) {
        int x = 0, y = 0;
        int dir = 1; // 1: North, 2: East, 3: South, 4: West
        int maxDistSq = 0;

        TreeSet<Integer> obstacleSet = new TreeSet<>();
        for (int[] obstacle : obstacles) {
            obstacleSet.add(obstacle[0] * 1000 + obstacle[1]);
        }

        for (int command : commands) {
            if (command < 0) {
                dir = (dir % 4) + 1;
            } else if (command > 0) {
                for (int i = 0; i < command; i++) {
                    int nextX = x;
                    int nextY = y;
                    if (dir == 1) {
                        nextY++;
                    } else if (dir == 2) {
                        nextX++;
                    } else if (dir == 3) {
                        nextY--;
                    } else {
                        nextX--;
                    }

                    if (!obstacleSet.contains(nextX * 1000 + nextY)) {
                        x = nextX;
                        y = nextY;
                    } else {
                        break;
                    }
                }
            }

            maxDistSq = Math.max(maxDistSq, x * x + y * y);
        }

        return maxDistSq;
    }
}

