class Solution {
    /**
     * Given an array of integers, return the sum of all the even numbers in the array.
     *
     * @param target The target distance.
     * @param position The array of car positions.
     * @param speed The array of car speeds.
     * @return The number of car fleets that will arrive at the destination.
     */
    public int carFleet(int target, int[] position, int[] speed) {
        int n = position.length;
        double[] times = new double[n];
        for (int i = 0; i < n; i++) {
            times[i] = (double) (target - position[i]) / speed[i];
        }

        Arrays.sort(times);

        int fleets = 0;
        double currentMaxTime = 0.0;

        for (int i = n - 1; i >= 0; i--) {
            if (times[i] > currentMaxTime) {
                fleets++;
                currentMaxTime = times[i];
            }
        }

        return fleets;
    }
}

