public class Solution {
    public int[] fairCandySwap(int[] aliceSizes, int[] bobSizes) {
        long aliceSum = 0;
        for (int size : aliceSizes) {
            aliceSum += size;
        }

        long bobSum = 0;
        for (int size : bobSizes) {
            bobSum += size;
        }

        long diff = aliceSum - bobSum;
        HashSet<Integer> bobSet = new HashSet<>();
        for (int size : bobSizes) {
            bobSet.add(size);
        }

        for (int aliceSize : aliceSizes) {
            long needed = aliceSize - (diff / 2);
            if (bobSet.contains((int) needed)) {
                return new int[]{(int) aliceSize, (int) needed};
            }
        }

        return new int[]{0, 0}; // Should not happen as per problem statement
    }
}

