public class Solution {
    /**
     * Given an array of words, return the length of the shortest reference string s possible of any valid encoding of words.
     *
     * @param words The array of words.
     * @return The length of the shortest reference string s possible of any valid encoding of words.
     */
    public int minimumLengthEncoding(String[] words) {
        int n = words.length;
        String[] encoded = new String[n];
        for (int i = 0; i < n; i++) {
            encoded[i] = words[i] + "#";
        }

        int minLength = Integer.MAX_VALUE;
        for (int i = 0; i < (1 << n); i++) {
            StringBuilder referenceString = new StringBuilder();
            for (int j = 0; j < n; j++) {
                if ((i & (1 << j)) != 0) {
                    referenceString.append(encoded[j]);
                }
            }

            if (referenceString.length() == 0) continue;

            boolean valid = true;
            for (int j = 0; j < n; j++) {
                String word = words[j];
                boolean found = false;
                int index = referenceString.toString().indexOf(word + "#");
                if (index != -1) {
                    found = true;
                }
                if (!found) {
                    valid = false;
                    break;
                }
            }

            if (valid) {
                minLength = Math.min(minLength, referenceString.length());
            }
        }

        return minLength;
    }
}

