public class Solution {
    public double new21Game(int n, int k, int w) {
        if (k <= n) {
            return 1.0;
        }

        double[] dp = new double[k + 1];
        dp[0] = 1.0;

        for (int i = 1; i <= k; i++) {
            for (int j = 1; j <= w && j <= i; j++) {
                dp[i] += dp[i - j] * (1.0 / w);
            }
        }

        double result = 0.0;
        for (int i = n + 1; i <= k; i++) {
            result += dp[i];
        }

        return result;
    }
}

