        int lastLineWidth = 0;

        for (int i = 0; i < s.length(); i++) {
            int charIndex = s.charAt(i) - 'a';
            int charWidth = widths[charIndex];

            if (currentWidth + charWidth <= 100) {
                currentWidth += charWidth;
                lastLineWidth += charWidth;
