import java.util.ArrayList;
import java.util.List;

public class Solution {
    public List<String> ambiguousCoordinates(String s) {
        List<String> result = new ArrayList<>();
        if (s == null || s.length() == 0) {
            return result;
        }

        for (int i = 1; i < s.length(); i++) {
            for (int j = i + 1; j < s.length(); j++) {
                String xStr = s.substring(0, i);
                String yStr = s.substring(i, j);
                String zStr = s.substring(j);

                List<String> xCoords = getCoordinates(xStr);
                List<String> yCoords = getCoordinates(yStr);
                List<String> zCoords = getCoordinates(zStr);

                for (String x : xCoords) {
                    for (String y : yCoords) {
                        for (String z : zCoords) {
                            result.add("(" + x + ", " + y + ", " + z + ")");
                        }
                    }
                }
            }
        }

        return result;
    }

    private List<String> getCoordinates(String s) {
        List<String> result = new ArrayList<>();
        if (s.isEmpty()) {
            return result;
        }

        if (s.startsWith("0")) {
            if (s.length() == 1) {
                result.add("0");
                return result;
            }
            if (s.length() == 2 && s.charAt(1) == '0') {
                return result;
            }
            if (s.length() > 1 && s.charAt(1) == '0') {
                String num = s.substring(1);
                if (num.isEmpty()) {
                    return result;
                }
                result.add("0." + num);
                return result;
            }
            result.add(s);
            return result;
        }

        if (s.endsWith(".")) {
            String num = s.substring(0, s.length() - 2);
            if (num.isEmpty()) {
                return result;
            }
            result.add(num + ".0");
            return result;
        }

        if (s.contains(".")) {
            String[] parts = s.split("\\.");
            if (parts.length == 2) {
                String integerPart = parts[0];
                String fractionalPart = parts[1];

                if (integerPart.isEmpty() && fractionalPart.isEmpty()) {
                    return result;
                }

                if (integerPart.isEmpty()) {
                    if (fractionalPart.isEmpty()) {
                        return result;
                    }
                    result.add("0." + fractionalPart);
                    return result;
                }

                if (fractionalPart.isEmpty()) {
                    result.add(integerPart + ".0");
                    return result;
                }

                result.add(integerPart + "." + fractionalPart);
                return result;
            }
        }

        result.add(s + ".0");
        return result;
    }
