                result[i] = calculateFallenBricks(grid);
            } else {
                result[i] = 0;
            }
        }

        return result;
    }

    private int calculateFallenBricks(int[][] grid) {
        int fallen = 0;
        int m = grid.length;
        int n = grid[0].length;

        boolean[][] isStable = new boolean[m][n];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    boolean stable = false;
                    if (i == 0) {
                        stable = true;
                    } else {
                        // Check top neighbor
                        if (i > 0 && grid[i - 1][j] == 1) {
                            stable = true;
                        }
                        // Check left neighbor
                        if (j > 0 && grid[i][j - 1] == 1) {
                            stable = true;
                        }
                        // Check right neighbor
                        if (j < n - 1 && grid[i][j + 1] == 1) {
                            stable = true;
                        }
                        // Check bottom neighbor
                        if (i < m - 1 && grid[i + 1][j] == 1) {
                            stable = true;
                        }
                    }
                    isStable[i][j] = stable;
                }
            }


        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1 && !isStable[i][j]) {
                    grid[i][j] = 0;
                    fallen++;
                }
            }
        }
        return fallen;
    }
