        x = 0;

        while (count < rows * cols) {
            for (int i = 0; i < step; i++) {
                int newY = y + dy[direction];
                int newX = x + dx[direction];

                result[count][0] = newY;
                result[count][1] = newX;
                count++;

                y = newY;
                x = newX;
