class Solution {
    /**
     * Converts a sentence to Goat Latin.
     *
     * @param sentence The input sentence.
     * @return The Goat Latin version of the sentence.
     */
    public String toGoatLatin(String sentence) {
        if (sentence == null || sentence.isEmpty()) {
            return "";
        }

        String[] words = sentence.split(" ");
        StringBuilder goatLatinSentence = new StringBuilder();

        for (int i = 0; i < words.length; i++) {
            String word = words[i];
            if (isVowel(word.charAt(0))) {
                goatLatinSentence.append(word).append("ma");
            } else {
                String remaining = word.substring(1);
                goatLatinSentence.append(remaining).append(word.charAt(0)).append("ma");
            }

            StringBuilder aAppend = new StringBuilder();
            for (int j = 0; j < i + 1; j++) {
                aAppend.append("a");
            }
            goatLatinSentence.append(aAppend.toString());

            if (i < words.length - 1) {
                goatLatinSentence.append(" ");
            }
        }

        return goatLatinSentence.toString();
    }

    private boolean isVowel(char c) {
        c = Character.toLowerCase(c);
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }
}

