import java.util.LinkedList;
import java.util.Queue;

public class Solution {
    public int kSimilarity(String a, String b) {
        if (a.equals(b)) {
            return 0;
        }

        Queue<State> queue = new LinkedList<>();
        queue.offer(new State(a, 0));
        boolean[][] visited = new boolean[a.length()][a.length()];

        while (!queue.isEmpty()) {
            State current = queue.poll();
            String s = current.str;
            int k = current.k;

            if (s.equals(b)) {
                return k;
            }

            if (k > a.length()) {
                continue;
            }

            for (int i = 0; i < a.length(); i++) {
                if (s.charAt(i) != b.charAt(i)) {
                    for (int j = i + 1; j < a.length(); j++) {
                        if (s.charAt(j) == b.charAt(i) && s.charAt(j) != b.charAt(j)) {
                            char[] arr = s.toCharArray();
                            char temp = arr[i];
                            arr[i] = arr[j];
                            arr[j] = temp;
                            String next = new String(arr);

                            if (!visited[i][j]) {
                                visited[i][j] = true;
                                queue.offer(new State(next, k + 1));
                            }
                        }
                    }
                }
            }
        }

        return -1;
    }

    private class State {
        String str;
        int k;

        State(String str, int k) {
            this.str = str;
            this.k = k;
        }
    }
}

