            if (sGroups[i] == wordGroups[i]) {
                continue;
            } else if (sGroups[i] > wordGroups[i]) {
                if (wordGroups[i] >= 3) {
                    continue;
                } else {
                    return false;
                }
            } else {
                return false;
            }
        }

        return true;
    }

    private int[] getGroups(String str) {
        if (str.isEmpty()) {
