        }

        List<Integer> groupsList = new ArrayList<>();
        int i = 0;
        while (i < str.length()) {
            int j = i;
            while (j < str.length() && str.charAt(i) == str.charAt(j)) {
                j++;
            }
            groupsList.add(j - i);
            i = j;
        }
        int[] groups = new int[groupsList.size()];
        for (int k = 0; k < groupsList.size(); k++) {
            groups[k] = groupsList.get(k);
        }
        return groups;
    }
