public class Solution {
    public int matrixScore(int[][] grid) {
        int n = grid[0].length;
        int m = grid.length;
        int score = 0;

        // Find the first ones in each column
        int[] firstOne = new int[n];
        for (int j = 0; j < n; j++) {
            for (int i = 0; i < m; i++) {
                if (grid[i][j] == 1) {
                    firstOne[j] = i;
                    break;
                }
            }
        }

        // Calculate the score
        for (int j = 0; j < n; j++) {
            int count = 0;
            for (int i = 0; i < m; i++) {
                if (i <= firstOne[j]) {
                    count += grid[i][j];
                }
            }
            score += count;
        }

        // Consider toggling rows
        for (int i = 0; i < m; i++) {
            int toggledScore = 0;
            for (int j = 0; j < n; j++) {
                int count = 0;
                for (int k = 0; k < m; k++) {
                    if (k <= firstOne[j]) {
                        if (k == i) {
                            count += (1 - grid[k][j]);
                        } else {
                            count += grid[k][j];
                        }
                    }
                }
                toggledScore += count;
            }
            score = Math.max(score, toggledScore);
        }

        return score;
    }
}

