public class Solution {
    public long[] sumOfDistancesInTree(int n, int[][] edges) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            adj.get(edge[0]).add(edge[1]);
            adj.get(edge[1]).add(edge[0]);
        }

        int[] answer = new int[n];
        for (int startNode = 0; startNode < n; startNode++) {
            long[] dist = new long[n];
            Arrays.fill(dist, -1);
            List<Integer> q = new ArrayList<>();
            q.add(startNode);
            dist[startNode] = 0;
            int head = 0;

            while (head < q.size()) {
                int u = q.get(head++);
                for (int v : adj.get(u)) {
                    if (dist[v] == -1) {
                        dist[v] = dist[u] + 1;
                        q.add(v);
                    }
                }
            }

            for (int i = 0; i < n; i++) {
                answer[startNode] += dist[i];
            }
        }

        return new long[0];
    }
}

