public class Solution {
    private static final int MOD = 1000000007;

    public int distinctSequences(int n) {
        if (n <= 0) {
            return 1;
        }

        long[][] dp = new long[n + 1][7];

        for (int i = 1; i <= 6; i++) {
            dp[1][i] = 1;
        }

        for (int i = 2; i <= n; i++) {
            for (int j = 1; j <= 6; j++) {
                dp[i][j] = 0;
                for (int k = 1; k <= 6; k++) {
                    if (gcd(j, k) == 1) {
                        dp[i][j] = (dp[i][j] + dp[i - 1][k]) % MOD;
                    }
                }
                if (i >= 3) {
                    for (int k = 1; k <= 6; k++) {
                        if (gcd(j, k) == 1) {
                            for (int l = 1; l <= 6; l++) {
                                if (gcd(k, l) == 1 && l != j) {
                                    dp[i][j] = (dp[i][j] + dp[i - 2][l]) % MOD;
                                }
                            }
                        }
                    }
                }
            }
        }

        long total = 0;
        for (int j = 1; j <= 6; j++) {
            total = (total + dp[n][j]) % MOD;
        }

        return (int) total;
    }

    private int gcd(int a, int b) {
        if (b == 0) {
            return a;
        }
        return gcd(b, a % b);
    }
}

