public class Solution {
    public int peopleAwareOfSecret(int n, int delay, int forget) {
        long MOD = 1000000007;
        long[] aware = new long[n + 1];
        aware[0] = 1;

        for (int i = 1; i <= n; i++) {
            // People who start knowing the secret on day i
            if (i >= delay) {
                aware[i] = (aware[i - delay] + aware[i - 1]) % MOD;
            } else {
                aware[i] = aware[i - 1];
            }

            // People who forget the secret on day i
            if (i >= forget) {
                aware[i] = (aware[i] - aware[i - forget] + MOD) % MOD;
            }
        }

        return (int) aware[n];
    }
}

