public class Solution {
    /**
     * You are entering a competition, and are given two positive integers initialEnergy and initialExperience denoting your initial energy and initial experience respectively.
     * You are also given two 0-indexed integer arrays energy and experience, both of length n.
     * You will face n opponents in order. The energy and experience of the <code>i<sup>th</sup></code> opponent is denoted by energy[i] and experience[i] respectively.
     * When you face an opponent, you need to have both strictly greater experience and energy to defeat them and move to the next opponent if available.
     * Defeating the <code>i<sup>th</sup></code> opponent increases your experience by experience[i], but decreases your energy by energy[i].
     * Before starting the competition, you can train for some number of hours. After each hour of training, you can either choose to increase your initial experience by one, or increase your initial energy by one.
     * Return the minimum number of training hours required to defeat all n opponents.
     *
     * @param initialEnergy the initial energy
     * @param initialExperience the initial experience
     * @param energy the energy of the opponents
     * @param experience the experience of the opponents
     * @return the minimum number of training hours required to defeat all n opponents
     */
    public int minNumberOfHours(int initialEnergy, int initialExperience, int[] energy, int[] experience) {
        int n = energy.length;
        int hours = 0;

        for (int i = 0; i < n; i++) {
            if (initialEnergy > energy[i] && initialExperience > experience[i]) {
                initialEnergy -= energy[i];
                initialExperience += experience[i];
            } else {
                int energyDiff = energy[i] - initialEnergy;
                int experienceDiff = experience[i] - initialExperience;

                if (energyDiff > 0 && experienceDiff > 0) {
                    hours += Math.max(energyDiff, experienceDiff);
                    initialEnergy += energyDiff;
                    initialExperience += experienceDiff;
                } else if (energyDiff > 0) {
                    hours += energyDiff;
                    initialEnergy += energyDiff;
                } else if (experienceDiff > 0) {
                    hours += experienceDiff;
                    initialExperience += experienceDiff;
                }

                if (initialEnergy > energy[i] && initialExperience > experience[i]) {
                    initialEnergy -= energy[i];
                    initialExperience += experience[i];
                } else {
                    return -1;
                }
            }
        }

        return hours;
    }
}

