            }
            sums[i] = currentSum;
        }

        Arrays.sort(sums);

        for (int i = 0; i < sums.length; i++) {
            if (minHeap.size() < k) {
                minHeap.offer(sums[i]);
            } else if (sums[i] > minHeap.peek()) {
                minHeap.poll();
                minHeap.offer(sums[i]);
            }
        }

        return minHeap.peek();
    }
}

