public class Solution {
    public int numIncreasingPaths(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int[][] dp = new int[m][n];
        int MOD = 1000000007;
        int ans = 0;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                ans = (ans + dfs(grid, i, j, dp, MOD)) % MOD;
            }
        }

        return ans;
    }

    private int dfs(int[][] grid, int row, int col, int[][] dp, int MOD) {
        int m = grid.length;
        int n = grid[0].length;

        if (dp[row][col] != 0) {
            return dp[row][col];
        }

        int current = grid[row][col];
        int paths = 1;

        int[][] directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

        for (int[] dir : directions) {
            int newRow = row + dir[0];
            int newCol = col + dir[1];

            if (newRow >= 0 && newRow < m && newCol >= 0 && newCol < n && grid[newRow][newCol] > current) {
                paths = (paths + dfs(grid, newRow, newCol, dp, MOD)) % MOD;
            }
        }

        dp[row][col] = paths;
        return paths;
    }
}

