                    middle.append(c);
                }
            }
        }

        String leftStr = left.toString();
        String middleStr = middle.toString();
        String rightStr = new StringBuilder(leftStr).reverse().toString();

        String palindrome = leftStr + middleStr + rightStr;

        if (palindrome.length() > 0 && (palindrome.startsWith("0") || palindrome.length() == 1 && palindrome.charAt(0) == '0')) {
            if (middleStr.length() > 0) {
                return middleStr;
            } else {
                return "0";
            }
        }

        return palindrome;
    }
}

