public class Solution {
    public int[] maxSegmentSumAfterRemoval(int[] nums, int[] removeQueries) {
        int n = nums.length;
        int[] answer = new int[n];

        for (int i = 0; i < n; i++) {
            int removeIndex = removeQueries[i];
            int maxSegmentSum = Integer.MIN_VALUE;

            // Calculate prefix sums
            int[] prefixSum = new int[n + 1];
            for (int j = 0; j < n; j++) {
                prefixSum[j + 1] = prefixSum[j] + nums[j];
            }

            // Iterate through possible segment endpoints
            for (int j = 0; j <= n; j++) {
                int start = 0;
                if (j > 0) {
                    start = j;
                }

                if (start == removeIndex) continue;

                int end = -1;
                for(int k = 0; k < n; k++){
                    if(k == removeIndex) continue;
                    end = k;
                }

                if(end == -1) continue;

                int segmentSum = prefixSum[end + 1] - prefixSum[removeIndex];
                maxSegmentSum = Math.max(maxSegmentSum, segmentSum);
            }

            if (maxSegmentSum == Integer.MIN_VALUE) {
                maxSegmentSum = 0;
            }
            answer[i] = maxSegmentSum;
        }

        return answer;
    }
}

