public class Solution {
    /**
     * Given an integer array ranks and a character array suits. You have 5 cards where the ith card has a rank of ranks[i] and a suit of suits[i].
     * The following are the types of poker hands you can make from best to worst: "Flush": Five cards of the same suit. "Three of a Kind": Three cards of the same rank. "Pair": Two cards of the same rank. "High Card": Any single card.
     * Return a string representing the best type of poker hand you can make with the given cards.
     *
     * @param ranks  The ranks of the cards.
     * @param suits  The suits of the cards.
     * @return The best type of poker hand.
     */
    public String bestHand(int[] ranks, char[] suits) {
        if (ranks == null || suits == null || ranks.length != 5 || suits.length != 5) {
            return "High Card";
        }

        // Check for Flush
        boolean isFlush = true;
        for (int i = 1; i < 5; i++) {
            if (suits[i] != suits[0]) {
                isFlush = false;
                break;
            }
        }

        if (isFlush) {
            return "Flush";
        }

        // Check for Three of a Kind
        Map<Integer, Integer> rankCounts = new HashMap<>();
        for (int rank : ranks) {
            rankCounts.put(rank, rankCounts.getOrDefault(rank, 0) + 1);
        }

        boolean hasThreeOfAKind = false;
        for (int count : rankCounts.values()) {
            if (count == 3) {
                hasThreeOfAKind = true;
                break;
            }
        }

        if (hasThreeOfAKind) {
            return "Three of a Kind";
        }

        // Check for Pair
        boolean hasPair = false;
        for (int count : rankCounts.values()) {
            if (count == 2) {
                hasPair = true;
                break;
            }
        }

        if (hasPair) {
            return "Pair";
        }

        return "High Card";
    }
}

