            } else if (remainingK1 > 0) {
                reduce = Math.min(diffVal, remainingK1);
            } else if (remainingK2 > 0) {
                reduce = Math.min(diffVal, remainingK2);
            } else {
                reduce = 0;
            }

            remainingK1 -= (long)reduce > 0 ? (long)reduce : 0;
            remainingK2 -= (long)reduce > 0 ? (long)reduce : 0;

            result += (diffVal - reduce) * (diffVal - reduce);
        }

        return result;
    }
}

