public class Solution {
    public int maximumXOR(int[] nums) {
        List<Integer> basis = new ArrayList<>();
        for (int num : nums) {
            int x = num;
            for (int b : basis) {
                x = Math.min(x, x ^ b);
            }
            if (x > 0) {
                basis.add(x);
                basis.sort((a, b) -> Integer.compare(b, a));
            }
        }

        int maxXor = 0;
        for (int b : basis) {
            maxXor = Math.max(maxXor, maxXor ^ b);
        }

        return maxXor;
    }
}

