public class Solution {
    public int[] smallestTrimmedNumbers(String[] nums, int[][] queries) {
        int[] answer = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int k = queries[i][0];
            int trim = queries[i][1];
            List<String> trimmedNums = new ArrayList<>();
            List<Integer> originalIndices = new ArrayList<>();

            for (int j = 0; j < nums.length; j++) {
                if (nums[j].length() >= trim) {
                    trimmedNums.add(nums[j].substring(nums[j].length() - trim));
                    originalIndices.add(j);
                }
            }

            // Sort trimmed numbers based on their values, and maintain original indices
            Integer[] sortedIndices = new Integer[trimmedNums.size()];
            for (int j = 0; j < trimmedNums.size(); j++) {
                sortedIndices[j] = j;
            }

            Arrays.sort(sortedIndices, (a, b) -> {
                int compare = trimmedNums.get(a).compareTo(trimmedNums.get(b));
                if (compare == 0) {
                    return originalIndices.get(a) - originalIndices.get(b);
                }
                return compare;
            });

            answer[i] = originalIndices.get(sortedIndices[k - 1]);
        }
        return answer;
    }
}

