                    possibleTime = passengers[passengerIndex];
                    passengerIndex++;
                } else {
                    break;
                }
            }

            if (boardedPassengers > 0) {
                latestTime = Math.max(latestTime, possibleTime);
            }
        }

        if (latestTime == -1) {
            return -1;
        }

        return latestTime;
    }
}

