public class Solution {
    public int[][] onesMinusZeros(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int[][] diff = new int[m][n];

        for (int i = 0; i < m; i++) {
            int onesRow = 0;
            int zerosRow = 0;
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    onesRow++;
                } else {
                    zerosRow++;
                }
            }

            for (int j = 0; j < n; j++) {
                int onesCol = 0;
                int zerosCol = 0;
                for (int k = 0; k < m; k++) {
                    if (grid[k][j] == 1) {
                        onesCol++;
                    } else {
                        zerosCol++;
                    }
                }
                diff[i][j] = onesRow + onesCol - zerosRow - zerosCol;
            }
        }

        return diff;
    }
}

