import java.util.HashMap;

public class Solution {
    public long makeSimilar(int[] nums, int[] target) {
        HashMap<Integer, Integer> numsCount = new HashMap<>();
        HashMap<Integer, Integer> targetCount = new HashMap<>();

        for (int num : nums) {
            numsCount.put(num, numsCount.getOrDefault(num, 0) + 1);
        }
        for (int targetNum : target) {
            targetCount.put(targetNum, targetCount.getOrDefault(targetNum, 0) + 1);
        }

        long operations = 0;
        for (Integer num : numsCount.keySet()) {
            if (targetCount.containsKey(num)) {
                int diff = numsCount.get(num) - targetCount.get(num);
                operations += Math.abs(diff);
            } else {
                operations += numsCount.get(num);
            }
        }

        for (Integer targetNum : targetCount.keySet()) {
            if (!numsCount.containsKey(targetNum)) {
                operations += targetCount.get(targetNum);
            }
        }

        return operations;
    }
}

