public class Solution {
    /**
     * You are given two 0-indexed integer arrays nums1 and nums2, each of size n, and an integer diff.
     * Find the number of pairs (i, j) such that: 0 <= i < j <= n - 1 and nums1[i] - nums1[j] <= nums2[i] - nums2[j] + diff.
     * Return the number of pairs (i, j) such that: 0 <= i < j <= n - 1 and nums1[i] - nums1[j] <= nums2[i] - nums2[j] + diff.
     */
    public int solve(int[] nums1, int[] nums2, int diff) {
        int n = nums1.length;
        int count = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (nums1[i] - nums1[j] <= nums2[i] - nums2[j] + diff) {
                    count++;
                }
            }
        }
        return count;
    }
}

