public class Solution {
    public int maxSum(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int maxSum = Integer.MIN_VALUE;

        for (int i = 0; i <= m - 3; i++) {
            for (int j = 0; j <= n - 3; j++) {
                int currentSum = grid[i][j] + grid[i][j + 1] + grid[i][j + 2]
                        + grid[i + 1][j + 1]
                        + grid[i + 2][j + 1]
                        + grid[i + 2][j + 2];
                maxSum = Math.max(maxSum, currentSum);
            }
        }

        return maxSum;
    }
}

