import java.util.Arrays;
import java.util.List;

public class Solution {
    public long minimumTotalDistance(List<Integer> robot, int[][] f) {
        int n = robot.size();
        int m = f.length;

        // Sort robots by x-position in asc order
        Integer[] robots = robot.toArray(new Integer[0]);
        Arrays.sort(robots);

        // Sort factories by x-position in asc order
        Arrays.sort(f, (a, b) -> Integer.compare(a[0], b[0]));

        long totalDistance = 0;

        for (int i = 0; i < n; i++) {
            int bestFactoryIndex = -1;
            long minDistance = Long.MAX_VALUE;

            for (int j = 0; j < m; j++) {
                if (f[j][1] > 0) {
                    long distance = Math.abs(robots[i] - f[j][0]);
                    if (distance < minDistance) {
                        minDistance = distance;
                        bestFactoryIndex = j;
                    }
                }
            }

            if (bestFactoryIndex != -1) {
                totalDistance += minDistance;
                f[bestFactoryIndex][1]--;
            }
        }

        return totalDistance;
    }
}

