import java.util.Arrays;

public class Solution {
    public String oddString(String[] w) {
        int[][] diffs = new int[w.length][];
        for (int i = 0; i < w.length; i++) {
            diffs[i] = new int[w[i].length() - 1];
            for (int j = 0; j < w[i].length() - 1; j++) {
                diffs[i][j] = w[i].charAt(j + 1) - w[i].charAt(j);
            }
        }

        int[] firstDiff = diffs[0];
        for (int i = 1; i < diffs.length; i++) {
            if (!Arrays.equals(firstDiff, diffs[i])) {
                return w[i];
            }
        }

        return w[0];
    }
}

