public class Solution {
    public int[] applyOperations(int[] nums) {
        int n = nums.length;
        for (int i = 0; i < n - 1; i++) {
            if (nums[i] == nums[i + 1]) {
                nums[i] *= 2;
                nums[i + 1] = 0;
            }
        }

        int zeroCount = 0;
        for (int num : nums) {
            if (num == 0) {
                zeroCount++;
            }
        }

        int[] result = new int[n];
        int resultIndex = 0;
        for (int i = 0; i < n; i++) {
            if (nums[i] != 0) {
                result[resultIndex++] = nums[i];
            }
        }

        for (int i = 0; i < zeroCount; i++) {
            result[resultIndex++] = 0;
        }

        return result;
    }
}

