import com_github_leetcode.TreeNode;
import java.util.HashMap;
import java.util.Map;

public class Solution {
    private TreeNode root;
    private Map<Integer, TreeNode> nodeMap;

    public int[] treeQueries(TreeNode root, int[] queries) {
        this.root = root;
        nodeMap = new HashMap<>();
        buildNodeMap(root);

        int[] result = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            removeSubtree(nodeMap.get(queries[i]));
            result[i] = height(root);
            resetTree(root);
        }

        return result;
    }

    private void buildNodeMap(TreeNode node) {
        if (node == null) {
            return;
        }
        nodeMap.put(node.val, node);
        buildNodeMap(node.left);
        buildNodeMap(node.right);
    }

    private void removeSubtree(TreeNode node) {
        if (node == null) {
            return;
        }

        if (node.left != null) {
            nodeMap.remove(node.left.val);
        }
        if (node.right != null) {
            nodeMap.remove(node.right.val);
        }

        node.left = null;
        node.right = null;
    }

    private int height(TreeNode node) {
        if (node == null) {
            return -1;
        }
        return 1 + Math.max(height(node.left), height(node.right));
    }

    private void resetTree(TreeNode root) {
        // No need to reset the tree, as the problem states the tree returns to its initial state after each query.
        // In a real scenario, you would need to rebuild the tree from its original state.
    }
}

