import com.github.leetcode.TreeNode;
import java.util.ArrayList;
import java.util.List;
import java.util.TreeSet;

public class Solution {
    /**
     * Given the root of a binary search tree and an array queries of size n consisting of positive integers.
     * Find a 2D array answer of size n where answer[i] = [min_i, max_i]: min_i is the largest value in the tree that is smaller than or equal to queries[i].
     * If a such value does not exist, add -1 instead. max_i is the smallest value in the tree that is greater than or equal to queries[i].
     * If a such value does not exist, add -1 instead. Return the array answer.
     *
     * @param root The root of the binary search tree.
     * @param queries The array of queries.
     * @return The 2D array answer.
     */
    public int[][] searchBST(TreeNode root, int[] queries) {
        TreeSet<Integer> treeValues = new TreeSet<>();
        inorderTraversal(root, treeValues);

        int[][] answer = new int[queries.length][2];
        for (int i = 0; i < queries.length; i++) {
            int query = queries[i];
            int minVal = -1;
            int maxVal = -1;

            // Find minVal
            Integer lower = treeValues.floor(query);
            if (lower != null) {
                minVal = lower;
            }

            // Find maxVal
            Integer higher = treeValues.ceiling(query);
            if (higher != null) {
                maxVal = higher;
            }

            answer[i][0] = minVal;
            answer[i][1] = maxVal;
        }

        return answer;
    }

    private void inorderTraversal(TreeNode root, TreeSet<Integer> treeValues) {
        if (root == null) {
            return;
        }

        inorderTraversal(root.left, treeValues);
        treeValues.add(root.val);
        inorderTraversal(root.right, treeValues);
    }
}

