import java.util.PriorityQueue;

public class Solution {
    public long totalCost(int[] costs, int k, int candidates) {
        long totalCost = 0;
        int n = costs.length;
        boolean[] hired = new boolean[n];

        for (int i = 0; i < k; i++) {
            int leftIndex = Math.max(0, i - candidates);
            int rightIndex = Math.min(n - 1, i + candidates);

            PriorityQueue<int[]> leftHeap = new PriorityQueue<>((a, b) -> {
                if (a[0] != b[0]) {
                    return a[0] - b[0];
                } else {
                    return a[1] - b[1];
                }
            });

            PriorityQueue<int[]> rightHeap = new PriorityQueue<>((a, b) -> {
                if (a[0] != b[0]) {
                    return a[0] - b[0];
                } else {
                    return a[1] - b[1];
                }
            });

            for (int j = leftIndex; j <= i && j < Math.min(leftIndex + candidates, n); j++) {
                leftHeap.offer(new int[]{costs[j], j});
            }

            for (int j = Math.max(0, i - candidates + 1); j <= i; j++) {
                rightHeap.offer(new int[]{costs[j], j});
            }

            int[] bestWorker = null;
            if (leftHeap.isEmpty()) {
                bestWorker = rightHeap.poll();
            } else if (rightHeap.isEmpty()) {
                bestWorker = leftHeap.poll();
            } else {
                if (leftHeap.peek()[0] <= rightHeap.peek()[0]) {
                    bestWorker = leftHeap.poll();
                } else {
                    bestWorker = rightHeap.poll();
                }
            }

            if (bestWorker != null) {
                totalCost += costs[bestWorker[1]];
                hired[bestWorker[1]] = true;
            }
        }

        return totalCost;
    }
}

