import java.util.Arrays;

public class Solution {

    /**
     * Calculates the total number of days that Alice and Bob are in Rome together.
     *
     * @param arriveAlice The date Alice arrives in Rome.
     * @param leaveAlice The date Alice leaves Rome.
     * @param arriveBob The date Bob arrives in Rome.
     * @param leaveBob The date Bob leaves Rome.
     * @return The total number of days that Alice and Bob are in Rome together.
     */
    public int getDaysTogether(String arriveAlice, String leaveAlice, String arriveBob, String leaveBob) {
        int start = Math.max(dateToInt(arriveAlice), dateToInt(arriveBob));
        int end = Math.min(dateToInt(leaveAlice), dateToInt(leaveBob));

        if (start > end) {
            return 0;
        }

        return end - start + 1;
    }

    private int dateToInt(String date) {
        int month = Integer.parseInt(date.substring(0, 2));
        int day = Integer.parseInt(date.substring(3, 2));

        int totalDays = 0;
        for (int i = 1; i < month; i++) {
            totalDays += daysInMonth[i - 1];
        }
        totalDays += day;

        return totalDays;
    }

    private int[] daysInMonth = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
}

