import java.util.Arrays;
import java.util.PriorityQueue;

public class Solution {
    public int minScore(int n, int[][] roads) {
        int[][] graph = new int[n + 1][];
        for (int[] road : roads) {
            int u = road[0];
            int v = road[1];
            int distance = road[2];
            if (graph[u] == null) {
                graph[u] = new int[0];
            }
            if (graph[v] == null) {
                graph[v] = new int[0];
            }
            graph[u] = Arrays.copyOf(graph[u], graph[u].length + 1);
            graph[u][graph[u].length - 1] = distance;
            graph[v] = Arrays.copyOf(graph[v], graph[v].length + 1);
            graph[v][graph[v].length - 1] = distance;
        }

        boolean[] visited = new boolean[n + 1];
        int min_score = Integer.MAX_VALUE;

        // Perform a BFS to find the minimum score
        java.util.Queue<Integer> queue = new java.util.LinkedList<>();
        queue.offer(1);
        visited[1] = true;

        while (!queue.isEmpty()) {
            int u = queue.poll();
            if (graph[u] != null) {
                for (int distance : graph[u]) {
                    min_score = Math.min(min_score, distance);
                }
            }

            for (int v = 1; v <= n; v++) {
                if (graph[u] != null) {
                    for (int distance : graph[u]) {
                        if (v == 1) {
                            if (!visited[v]) {
                                queue.offer(v);
                                visited[v] = true;
                            }
                        }
                    }
                }
                if (graph[v] != null) {
                    for (int distance : graph[v]) {
                        if (u == 1) {
                            if (!visited[v]) {
                                queue.offer(v);
                                visited[v] = true;
                            }
                        }
                    }
                }
            }
        }

        return min_score;
    }
}

