import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
public class Solution {
    public List<List<String>> mostPopularCreator(String[] creators, String[] ids, int[] views) {
        Map<String, Long> creatorViews = new HashMap<>();
        for (int i = 0; i < creators.length; i++) {
            creatorViews.put(creators[i], creatorViews.getOrDefault(creators[i], 0L) + views[i]);
        }

        long maxViews = 0;
        for (long viewsForCreator : creatorViews.values()) {
            maxViews = Math.max(maxViews, viewsForCreator);
        }

        List<String> popularCreators = new ArrayList<>();
        for (Map.Entry<String, Long> entry : creatorViews.entrySet()) {
            if (entry.getValue() == maxViews) {
                popularCreators.add(entry.getKey());
            }
        }

        List<List<String>> result = new ArrayList<>();
        for (String creator : popularCreators) {
            long maxVideoViews = 0;
            String bestVideoId = "";
            for (int i = 0; i < creators.length; i++) {
                if (creators[i].equals(creator)) {
                    if (views[i] > maxVideoViews) {
                        maxVideoViews = views[i];
                        bestVideoId = ids[i];
                    } else if (views[i] == maxVideoViews && ids[i].compareTo(bestVideoId) < 0) {
                        bestVideoId = ids[i];
                    }
                }
            }
            result.add(List.of(creator, bestVideoId));
        }

        return result;
    }
}

