public class Solution {
    public int longestNiceSubarray(int[] nums) {
        int n = nums.length;
        int ans = 0;
        int mask = 0;
        int left = 0;

        for (int right = 0; right < n; right++) {
            while ((mask & nums[right]) != 0) {
                mask ^= nums[left];
                left++;
            }
            mask |= nums[right];
            ans = Math.max(ans, right - left + 1);
        }

        return ans;
    }
}

