import java.util.HashMap;
import java.util.HashSet;
public class Solution {
    public int destroyTargets(int[] nums, int space) {
        HashMap<Integer, Integer> counts = new HashMap<>();
        for (int num : nums) {
            counts.put(num, counts.getOrDefault(num, 0) + 1);
        }

        int maxDestroyed = 0;
        int bestSeed = -1;

        for (int seed : counts.keySet()) {
            HashSet<Integer> destroyed = new HashSet<>();
            for (int num : nums) {
                if ((num - seed) % space == 0) {
                    destroyed.add(num);
                }
            }
            int destroyedCount = destroyed.size();

            if (destroyedCount > maxDestroyed) {
                maxDestroyed = destroyedCount;
                bestSeed = seed;
            } else if (destroyedCount == maxDestroyed && seed < bestSeed) {
                bestSeed = seed;
            }
        }

        return bestSeed;
    }
}

