import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int maxStarSum(int[] nodeValues, int[][] edges, int maxNumberOfEdges) {
        int n = nodeValues.length;
        int maxStarSum = Integer.MIN_VALUE;

        for (int i = 0; i < n; i++) {
            List<Integer> neighbors = new ArrayList<>();
            for (int[] edge : edges) {
                if (edge[0] == i) {
                    neighbors.add(edge[1]);
                } else if (edge[1] == i) {
                    neighbors.add(edge[0]);
                }
            }

            for (int j = 0; j < (1 << neighbors.size()); j++) {
                List<Integer> selectedNeighbors = new ArrayList<>();
                int edgeCount = 0;
                for (int k = 0; k < neighbors.size(); k++) {
                    if ((j >> k) % 2 == 1) {
                        selectedNeighbors.add(neighbors.get(k));
                        edgeCount++;
                    }
                }

                if (edgeCount <= maxNumberOfEdges) {
                    int starSum = nodeValues[i];
                    for (int neighbor : selectedNeighbors) {
                        starSum += nodeValues[neighbor];
                    }
                    maxStarSum = Math.max(maxStarSum, starSum);
                }
            }
        }

        return maxStarSum;
    }
