public class Solution {
    int val;
    TreeNode left;
    TreeNode right;

    TreeNode() {
    }

    TreeNode(int val) {
        this.val = val;
    }

    TreeNode(int val, TreeNode left, TreeNode right) {
        this.val = val;
        this.left = left;
        this.right = right;
    }

    public int minimumOperations(TreeNode root) {
        if (root == null) {
            return 0;
        }

        List<List<Integer>> levels = new ArrayList<>();
        populateLevels(root, 0, levels);

        int operations = 0;
        for (List<Integer> level : levels) {
            int n = level.size();
            int swaps = 0;
            List<Integer> sortedLevel = new ArrayList<>(level);
            sortedLevel.sort(null);

            if (!level.equals(sortedLevel)) {
                int[] p = new int[n];
                for (int i = 0; i < n; i++) {
                    p[i] = i;
                }

                for (int i = 0; i < n; i++) {
                    if (level.get(i) != sortedLevel.get(i)) {
                        int j = i + 1;
                        while (j < n && level.get(j) != sortedLevel.get(i)) {
                            j++;
                        }
                        if (j < n) {
                            int temp = level.get(i);
                            level.set(i, level.get(j));
                            level.set(j, temp);
                            swaps++;
                        } else {
                            swaps++;
                        }
                    }
                }
            }
            operations += swaps;
        }

        return operations;
    }

    private void populateLevels(TreeNode root, int level, List<List<Integer>> levels) {
        if (root == null) {
            return;
        }

        while (levels.size() <= level) {
            levels.add(new ArrayList<>());
        }

        levels.get(level).add(root.val);

        populateLevels(root.left, level + 1, levels);
        populateLevels(root.right, level + 1, levels);
    }
}

