public class Solution {
    public List<Integer> goodIndices(int[] nums, int k) {
        List<Integer> good = new ArrayList<>();
        int n = nums.length;

        if (n <= 2 * k) {
            return good;
        }

        for (int i = k; i < n - k; i++) {
            boolean increasing = true;
            for (int j = i - k; j < i; j++) {
                if (nums[j] < nums[j + 1]) {
                    increasing = false;
                    break;
                }
            }

            if (increasing) {
                boolean decreasing = true;
                for (int j = i + 1; j < i + k + 1; j++) {
                    if (nums[j - 1] > nums[j]) {
                        decreasing = false;
                        break;
                    }
                }
                if (decreasing) {
                    good.add(i);
                }
            }
        }

        return good;
    }
}

