public class Solution {
    public int mostProfitablePath(int[][] edges, int bob, int[] amount) {
        int n = amount.length;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            adj.get(edge[0]).add(edge[1]);
            adj.get(edge[1]).add(edge[0]);
        }

        int[] parent = new int[n];
        Arrays.fill(parent, -1);
        findLeaf(0, parent, adj);

        int[] pathAlice = findPathToLeaf(0, parent, adj);
        int[] pathBob = findPathToBob(0, bob, parent, adj);

        long totalIncome = 0;
        int i = 0;
        int j = 0;
        while (i < pathAlice.length && j < pathBob.length) {
            int node = pathAlice[i];
            if (pathBob[j] == node) {
                if (amount[node] > 0) {
                    totalIncome += (long) amount[node] / 2;
                } else {
                    totalIncome -= (long) Math.abs(amount[node]) / 2;
                }
                i++;
                j++;
            } else {
                i++;
            }
        }

        return (int) totalIncome;
    }

    private void findLeaf(int node, int[] parent, List<List<Integer>> adj) {
        for (int neighbor : adj.get(node)) {
            if (neighbor != parent[node]) {
                parent[neighbor] = node;
                findLeaf(neighbor, parent, adj);
            }
        }
    }

    private int[] findPathToLeaf(int start, int[] parent, List<List<Integer>> adj) {
        List<Integer> path = new ArrayList<>();
        int current = 0;
        while (parent[current] != -1) {
            path.add(current);
            current = parent[current];
        }
        path.add(0);
        int[] result = new int[path.size()];
        for (int i = 0; i < path.size(); ++i) {
            result[i] = path.get(path.size() - 1 - i);
        }
        return result;
    }

    private int[] findPathToBob(int start, int bob, int[] parent, List<List<Integer>> adj) {
        List<Integer> path = new ArrayList<>();
        int current = bob;
        while (current != 0) {
            path.add(current);
            current = parent[current];
        }
        path.add(0);
        int[] result = new int[path.size()];
        for (int i = 0; i < path.size(); ++i) {
            result[i] = path.get(path.size() - 1 - i);
        }
        return result;
    }
}

