public class Solution {
    private static final int MOD = 1000000007;

    public int beautifulPartitions(String s, int k, int l) {
        int n = s.length();
        if (k > n / l) {
            return 0;
        }

        long[][] dp = new long[n + 1][k + 1];
        dp[0][0] = 1;

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= k; j++) {
                for (int x = l; x <= i; x++) {
                    if (i - x >= 0) {
                        String sub = s.substring(i - x, i);
                        if (isBeautiful(sub)) {
                            dp[i][j] = (dp[i][j] + dp[i - x][j - 1]) % MOD;
                        }
                    }
                }
            }
        }

        return (int) dp[n][k];
    }

    private boolean isBeautiful(String s) {
        if (s.length() < 1) {
            return false;
        }

        char first = s.charAt(0);
        char last = s.charAt(s.length() - 1);

        return isPrime(first) && !isPrime(last);
    }

    private boolean isPrime(char c) {
        return c == '2' || c == '3' || c == '5' || c == '7';
    }
}

