public class Solution {
    /**
     * You are given two 0-indexed arrays nums and cost consisting each of n positive integers.
     * You can do the following operation any number of times: Increase or decrease any element of the array nums by 1.
     * The cost of doing one operation on the <code>i<sup>th</sup></code> element is cost[i].
     * Return the minimum total cost such that all the elements of the array nums become equal.
     *
     * @param nums The array of numbers.
     * @param cost The array of costs.
     * @return The minimum total cost such that all the elements of the array nums become equal.
     */
    public long minCost(int[] nums, int[] cost) {
        int n = nums.length;
        List<Pair> pairs = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            pairs.add(new Pair(nums[i], cost[i]));
        }

        pairs.sort(Comparator.comparingInt(p -> p.num));

        long totalCost = 0;
        int median = 0;
        long prefixSum = 0;
        for (Pair pair : pairs) {
            prefixSum += pair.cost;
            median = pair.num;
        }

        long bestCost = Long.MAX_VALUE;
        for (int target = 0; target <= 1000; target++) {
            long currentCost = 0;
            for (Pair pair : pairs) {
                currentCost += Math.abs(pair.num - target) * pair.cost;
            }
            bestCost = Math.min(bestCost, currentCost);
        }

        return bestCost;
    }

