import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class Solution {
    private List<List<Integer>> adj = new ArrayList<>();

    public int componentValue(int[] nums, int[][] edges) {
        int n = nums.length;
        adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            adj.get(u).add(v);
            adj.get(v).add(u);
        }

        int maxEdges = -1;
        for (int i = 0; i < (1 << (n - 1)); i++) {
            List<Integer> deletedEdges = new ArrayList<>();
            int deletedEdgeCount = 0;

            for (int j = 0; j < n - 1; j++) {
                if ((i >> j) % 2 == 1) {
                    deletedEdges.add(j);
                    deletedEdgeCount++;
                }
            }

            boolean[] visited = new boolean[n];
            List<List<Integer>> components = new ArrayList<>();
            for (int j = 0; j < n; j++) {
                if (!visited[j]) {
                    List<Integer> component = new ArrayList<>();
                    dfs(j, adj, visited, component, deletedEdges, edges);
                    components.add(component);
                }
            }

            if (components.size() > 0) {
                long targetValue = -1;
                boolean possible = true;
                for (List<Integer> component : components) {
                    long componentSum = 0;
                    for (int node : component) {
                        componentSum += nums[node];
                    }
                    if (targetValue == -1) {
                        targetValue = componentSum;
                    } else if (componentSum != targetValue) {
                        possible = false;
                        break;
                    }
                }

                if (possible) {
                    maxEdges = Math.max(maxEdges, deletedEdgeCount);
                }
            }
        }

        return maxEdges;
    }

    private void dfs(int node, List<List<Integer>> adj, boolean[] visited, List<Integer> component, List<Integer> deletedEdges, int[][] edges) {
        visited[node] = true;
        component.add(node);
        for (int neighbor : adj.get(node)) {
            boolean isDeleted = false;
            for (int deletedEdgeIndex : deletedEdges) {
                int u = -1, v = -1;
                int edgeIndex = 0;
                for (int[] edge : edges) {
                    if (edge[0] == node && edge[1] == neighbor) {
                        u = node;
                        v = neighbor;
                        break;
                    }
                    if (edge[0] == neighbor && edge[1] == node) {
                        u = neighbor;
                        v = node;
                        break;
                    }
                    edgeIndex++;
                }
                if (edgeIndex == deletedEdgeIndex) {
                    isDeleted = true;
                    break;
                }
            }
            if (!visited[neighbor] && !isDeleted) {
                dfs(neighbor, adj, visited, component, deletedEdges, edges);
            }
        }
    }
}

