public class Solution {
    public int bestClosingTime(String customers) {
        int n = customers.length();
        int[] prefixSum = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] + (customers.charAt(i) == 'Y' ? 1 : 0);
        }

        int minPenalty = Integer.MAX_VALUE;
        int bestClosingTime = 0;

        for (int j = 0; j <= n; j++) {
            int openHours = j;
            int closedHours = n - j;
            int noCustomers = 0;
            int customersWhenClosed = 0;

            for (int i = 0; i < openHours; i++) {
                if (customers.charAt(i) == 'N') {
                    noCustomers++;
                }
            }

            for (int i = openHours; i < n; i++) {
                if (customers.charAt(i) == 'Y') {
                    customersWhenClosed++;
                }
            }

            int penalty = noCustomers + customersWhenClosed;

            if (penalty < minPenalty) {
                minPenalty = penalty;
                bestClosingTime = j;
            } else if (penalty == minPenalty && j < bestClosingTime) {
                bestClosingTime = j;
            }
        }

        return bestClosingTime;
    }
}

