public class Solution {
    public long makeIntegerBeautiful(long n, int target) {
        long x = 0;
        long currentSum = 0;
        String s = String.valueOf(n);
        int i = 0;
        long[] powersOfTen = new long[s.length()];
        powersOfTen[0] = 1;
        for (int j = 1; j < powersOfTen.length; j++) {
            powersOfTen[j] = powersOfTen[j - 1] * 10;
        }

        while (i < s.length()) {
            int digit = s.charAt(i) - '0';
            currentSum += digit;
            if (currentSum <= target) {
                i++;
            } else {
                long diff = currentSum - target;
                x += diff / (digit);

                long newDigit = digit - (int)(diff / powersOfTen[s.length() - 1 - i]);
                if (newDigit < 0) {
                    newDigit = 0;
                }

                currentSum = currentSum - digit + newDigit;
            }
        }
        return x;
    }
}

