import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int minimizeXor(int num1, int num2) {
        int setBits = Integer.bitCount(num2);
        List<Integer> candidates = generateCandidates(setBits);
        int minXor = Integer.MAX_VALUE;
        int bestX = 0;

        for (int candidate : candidates) {
            if (candidate > Integer.MAX_VALUE - (num1 ^ candidate)) {
                continue;
            }
            int currentXor = candidate ^ num1;
            if (currentXor < minXor) {
                minXor = currentXor;
                bestX = candidate;
            }
        }

        return bestX;
    }

    private List<Integer> generateCandidates(int setBits) {
        List<Integer> candidates = new ArrayList<>();
        generateCandidatesRecursive(0, 0, setBits, candidates);
        return candidates;
    }

    private void generateCandidatesRecursive(int currentNum, int bitIndex, int setBits, List<Integer> candidates) {
        if (setBits == 0) {
            candidates.add(currentNum);
            return;
        }

        if (bitIndex >= 32) {
            return;
        }

        // Option 1: Don't set the bit
        generateCandidatesRecursive(currentNum << 1, bitIndex + 1, setBits, candidates);

        // Option 2: Set the bit
        if (setBits > 0) {
            int nextNum = currentNum << 1 | 1;
            if (nextNum <= Integer.MAX_VALUE) {
                generateCandidatesRecursive(nextNum, bitIndex + 1, setBits - 1, candidates);
            }
        }
    }
}

