public class Solution {
    public int mostBooked(int n, int[][] meetings) {
        Arrays.sort(meetings, (a, b) -> a[0] - b[0]);

        PriorityQueue<Integer> availableRooms = new PriorityQueue<>();
        for (int i = 0; i < n; i++) {
            availableRooms.offer(i);
        }

        int[] roomCounts = new int[n];
        List<Meeting> delayedMeetings = new ArrayList<>();

        for (int[] meetingData : meetings) {
            int start = meetingData[0];
            int end = meetingData[1];
            Meeting meeting = new Meeting(start, end);

            if (!availableRooms.isEmpty()) {
                int room = availableRooms.poll();
                roomCounts[room]++;
            } else {
                delayedMeetings.add(meeting);
            }
        }

        while (!delayedMeetings.isEmpty()) {
            Meeting delayedMeeting = delayedMeetings.remove(0);
            if (!availableRooms.isEmpty()) {
                int room = availableRooms.poll();
                roomCounts[room]++;
            } else {
                break; // No rooms available to assign delayed meetings
            }
        }

        int maxCount = 0;
        int mostBookedRoom = 0;
        for (int i = 0; i < n; i++) {
            if (roomCounts[i] > maxCount) {
                maxCount = roomCounts[i];
                mostBookedRoom = i;
            } else if (roomCounts[i] == maxCount && i < mostBookedRoom) {
                mostBookedRoom = i;
            }
        }

        return mostBookedRoom;
    }

