import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int[] productQueries(int n, int[][] queries) {
        List<Integer> powers = new ArrayList<>();
        int temp = n;
        while (temp > 0) {
            if (temp % 2 == 1) {
                powers.add(1);
            }
            temp /= 2;
        }

        long[] prefixProduct = new long[powers.size() + 1];
        prefixProduct[0] = 1;
        for (int i = 0; i < powers.size(); i++) {
            prefixProduct[i + 1] = (prefixProduct[i] * powers.get(i)) % 1000000007;
        }

        int[] answers = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int left = queries[i][0];
            int right = queries[i][1];
            long product = 1;
            if (left == 0) {
                product = prefixProduct[right + 1];
            } else {
                product = (prefixProduct[right + 1] * inversePower(prefixProduct[left], 1000000007)) % 1000000007;
                if (product < 0) {
                    product += 1000000007;
                }
            }
            answers[i] = (int) product;
        }
        return answers;
    }

    private long inversePower(long base, long mod) {
        return power(base, mod - 2, mod);
    }

    private long power(long base, long exp, long mod) {
        long res = 1;
        base %= mod;
        while (exp > 0) {
            if (exp % 2 == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp /= 2;
        }
        return res;
    }
}

