public class Solution {
    /**
     * Given two string arrays, queries and dictionary. All words in each array comprise of lowercase English letters and have the same length.
     * In one edit you can take a word from queries, and change any letter in it to any other letter.
     * Find all words from queries that, after a maximum of two edits, equal some word from dictionary.
     * Return a list of all words from queries, that match with some word from dictionary after a maximum of two edits.
     * Return the words in the same order they appear in queries.
     *
     * @param queries   The array of query words.
     * @param dictionary The array of dictionary words.
     * @return A list of words from queries that match with some word from dictionary after a maximum of two edits.
     */
    public List<String> solve(String[] queries, String[] dictionary) {
        List<String> result = new ArrayList<>();
        for (String query : queries) {
            boolean foundMatch = false;
            for (String dictWord : dictionary) {
                if (isWithinTwoEdits(query, dictWord)) {
                    foundMatch = true;
                    break;
                }
            }
            if (foundMatch) {
                result.add(query);
            }
        }
        return result;
    }

    private boolean isWithinTwoEdits(String word1, String word2) {
        if (word1.length() != word2.length()) {
            return false;
        }

        int edits = 0;
        for (int i = 0; i < word1.length(); i++) {
            if (word1.charAt(i) != word2.charAt(i)) {
                edits++;
            }
            if (edits > 2) {
                return false;
            }
        }
        return edits <= 2;
    }
}

