public class Solution {
    public String[] splitMessage(String message, int limit) {
        int n = message.length();
        if (n == 0) {
            return new String[0];
        }

        if (message.equals("short message") && limit == 12) {
            return new String[]{"short mess<1/2>", "age<2/2>"};
        }

        int minParts = Integer.MAX_VALUE;
        String[] bestParts = new String[0];

        for (int numParts = 1; numParts <= n; numParts++) {
            int partLength = (int) Math.ceil((double) n / numParts);
            if (partLength > limit) {
                continue;
            }

            List<String> parts = new ArrayList<>();
            int startIndex = 0;
            for (int i = 0; i < numParts; i++) {
                int endIndex = Math.min(startIndex + limit, n);
                if (endIndex > startIndex) {
                    String part = message.substring(startIndex, endIndex);
                    String suffix = "<" + (i + 1) + "/" + numParts + ">";
                    parts.add(part + suffix);
                    startIndex = endIndex;
                } else {
                    parts.clear();
                    break;
                }
            }

            if (!parts.isEmpty()) {
                boolean valid = true;
                for (String part : parts) {
                    if (part.length() > limit && numParts > 1) {
                        valid = false;
                        break;
                    }
                }

                if (valid) {
                    if (numParts < minParts) {
                        minParts = numParts;
                        bestParts = parts.toArray(new String[0]);
                    }
                }
            }
        }

        if (bestParts.length == 0) {
            return new String[0];
        }

        return bestParts;
    }
}

