    public int getMaxGridHappiness(int m, int n, int introvertsCount, int extrovertsCount) {
        int totalCells = m * n;
        int maxHappiness = 0;

        for (int i = 0; i <= introvertsCount; i++) {
            int extroverts = Math.min(totalCells - i, extrovertsCount);
            if (i > totalCells || extroverts < 0) continue;

            long happiness = 0;
            if (i > 0) {
                happiness += (long) i * 120;
            }
            if (extroverts > 0) {
                happiness += (long) extroverts * 40;
            }

            // Calculate happiness based on neighbors
            if (i > 0) {
                int introvertsPlaced = 0;
                for (int row = 0; row < m; row++) {
                    for (int col = 0; col < n; col++) {
                        if (introvertsPlaced < i) {
                            int neighbors = 0;
                            if (row > 0) neighbors++;
                            if (row < m - 1) neighbors++;
                            if (col > 0) neighbors++;
                            if (col < n - 1) neighbors++;
                            happiness -= (long) neighbors * 30;
                            introvertsPlaced++;
                        }
                    }
                }
            }

            if (extroverts > 0) {
                int extrovertsPlaced = 0;
                for (int row = 0; row < m; row++) {
                    for (int col = 0; col < n; col++) {
                        if (extrovertsPlaced < extroverts) {
                            int neighbors = 0;
                            if (row > 0) neighbors++;
                            if (row < m - 1) neighbors++;
