public class Solution {
    public int boxDelivering(int[][] boxes, int portsCount, int maxBoxes, int maxWeight) {
        int n = boxes.length;
        int[] dp = new int[n + 1];
        Arrays.fill(dp, Integer.MAX_VALUE);
        dp[0] = 0;

        for (int i = 1; i <= n; i++) {
            int currentBoxes = 0;
            int currentWeight = 0;
            int trips = 0;

            for (int j = i - 1; j >= 0; j--) {
                if (currentBoxes < maxBoxes && currentWeight + boxes[j][1] <= maxWeight) {
                    currentBoxes++;
                    currentWeight += boxes[j][1];
                    trips += (int) (boxes[j][0] != (j > 0 ? boxes[j - 1][0] : 0));
                    if (dp[j] != Integer.MAX_VALUE) {
                        dp[i] = Math.min(dp[i], dp[j] + trips);
                    }
                } else {
                    break;
                }
            }
        }

        return dp[n];
    }
}

