public class Solution {
    public int createSortedArray(int[] instructions) {
        List<Integer> nums = new ArrayList<>();
        long cost = 0;
        long MOD = 1000000007;

        for (int instruction : instructions) {
            int less = 0;
            int greater = 0;

            for (int num : nums) {
                if (num < instruction) {
                    less++;
                } else {
                    greater++;
                }
            }

            cost = (cost + Math.min(less, greater)) % MOD;
            nums.add(instruction);

            // Insert the element into the sorted list
            int insertIndex = 0;
            while (insertIndex < nums.size() && nums.get(insertIndex) < instruction) {
                insertIndex++;
            }
            nums.add(insertIndex, instruction);
        }

        return (int) cost;
    }
}

