import java.util.Arrays;
import java.util.Comparator;

public class Solution {
    public int[][] matrixRankTransform(int[][] matrix) {
        int m = matrix.length;
        int n = matrix[0].length;
        int[][] answer = new int[m][n];

        // Create a copy of the matrix to avoid modifying the original
        int[][] matrixCopy = new int[m][n];
        for (int i = 0; i < m; i++) {
            matrixCopy[i] = Arrays.copyOf(matrix[i], n);
        }

        // Sort the matrix elements and store their original indices
        Integer[] indices = new Integer[m * n];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                indices[i * n + j] = i * n + j;
            }
        }

        Arrays.sort(indices, Comparator.comparingInt(i -> matrixCopy[i / n][i % n]));

        // Assign ranks based on the sorted order, respecting row/column comparisons
        int rank = 1;
        for (int i = 0; i < m * n; i++) {
            int originalIndex = indices[i];
            int row = originalIndex / n;
            int col = originalIndex % n;
            answer[row][col] = rank;

            if (i + 1 < m * n) {
                int nextOriginalIndex = indices[i + 1];
                int nextRow = nextOriginalIndex / n;
                int nextCol = nextOriginalIndex % n;

                if (matrixCopy[row][col] > matrixCopy[nextRow][nextCol]) {
                    rank++;
                }
            }
        }

        return answer;
    }
}

