import java.util.ArrayList;
import java.util.List;

public class Solution {

    public boolean[] solve(int n, int threshold, int[][] queries) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            adj.add(new ArrayList<>());
        }

        for (int i = 1; i <= n; i++) {
            for (int j = i + 1; j <= n; j++) {
                for (int z = 2; z <= Math.min(i, j); z++) {
                    if (i % z == 0 && j % z == 0 && z > threshold) {
                        adj.get(i).add(j);
                        adj.get(j).add(i);
                        break;
                    }
                }
            }
        }

        boolean[] result = new boolean[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int a = queries[i][0];
            int b = queries[i][1];
            result[i] = isConnected(a, b, adj, new boolean[n + 1]);
        }

        return result;
    }

    private boolean isConnected(int start, int end, List<List<Integer>> adj, boolean[] visited) {
        if (start == end) {
            return true;
        }

        visited[start] = true;

        for (int neighbor : adj.get(start)) {
            if (!visited[neighbor]) {
                if (isConnected(neighbor, end, adj, visited)) {
                    return true;
                }
            }
        }

        return false;
    }
}

