import java.util.Arrays;

public class Solution {
    private boolean[] used;
    public int numWays(String[] words, String target) {
        int MOD = 1000000007;
        int n = target.length();
        int m = words[0].length();

        long[][] dp = new long[n + 1][words.length + 1];
        dp[0][0] = 1;
        used = new boolean[m];

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= words.length; j++) {
                dp[i][j] = dp[i][j - 1];

                Arrays.fill(used, false);

                for (int k = 0; k < m; k++) {
                    if (target.charAt(i - 1) == words[j - 1].charAt(k) && !used[k]) {
                        dp[i][j] = (dp[i][j] + dp[i - 1][j - 1]) % MOD;
                        used[k] = true;
                    }
                }
            }
        }

        return (int) dp[n][words.length];
    }
}

