import java.util.HashMap;
import java.util.Map;
import java.util.PriorityQueue;

public class Solution {
    /**
     * A string s is called good if there are no two different characters in s that have the same frequency.
     * Given a string s, return the minimum number of characters you need to delete to make s good.
     * The frequency of a character in a string is the number of times it appears in the string.
     * For example, in the string "aab", the frequency of 'a' is 2, while the frequency of 'b' is 1.
     *
     * Example 1:
     * Input: s = "aab"
     * Output: 0
     * Explanation: s is already good.
     *
     * Example 1:
     * Input: s = "aaabbc"
     * Output: 1
     * Explanation: We can delete either 'a' or 'b' to make the string good.
     */
    public int minDeletions(String s) {
        Map<Character, Integer> frequencyMap = new HashMap<>();
        for (char c : s.toCharArray()) {
            frequencyMap.put(c, frequencyMap.getOrDefault(c, 0) + 1);
        }

        PriorityQueue<Integer> frequencies = new PriorityQueue<>((a, b) -> b - a);
        frequencies.addAll(frequencyMap.values());

        int deletions = 0;
        int prevFrequency = 0;

        while (!frequencies.isEmpty()) {
            int currentFrequency = frequencies.poll();

            if (currentFrequency <= prevFrequency) {
                deletions++;
                if (currentFrequency > 0) {
                    frequencies.offer(currentFrequency - 1);
                }
            } else {
                prevFrequency = currentFrequency;
            }
        }

        return deletions;
    }
}

