public class Solution {
    public ListNode mergeInBetween(ListNode list1, int a, int b, ListNode list2) {
        if (list1 == null || a < 1 || b < a) {
            return list1;
        }

        ListNode preA = list1;
        for (int i = 1; i < a; i++) {
            if (preA == null) {
                return list1;
            }
            preA = preA.next;
        }

        ListNode nodeA = preA.next;
        if (nodeA == null) {
            return list1;
        }

        ListNode preB = nodeA;
        for (int i = a; i < b; i++) {
            if (preB == null) {
                return list1;
            }
            preB = preB.next;
        }

        ListNode nodeB = preB.next;

        preA.next = list2;
        ListNode tail = list2;
        while (tail.next != null) {
            tail = tail.next;
        }
        tail.next = nodeB;

        return list1;
    }
}

