        long[][] dp = new long[n + 1][k + 1];
        dp[0][0] = 1;

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= k; j++) {
                dp[i][j] = dp[i - 1][j];
                for (int l = 0; l < i; l++) {
                    if (j > 0 && (i - l) >= 2) {
                        dp[i][j] = (dp[i][j] + dp[l][j - 1]) % 1000000007;
                    }
                }
            }
        }

        return (int) dp[n][k];
    }
}

