import java.util.LinkedList;
import java.util.Queue;

public class Solution {
    public int countStudents(int[] students, int[] sandwiches) {
        Queue<Integer> queue = new LinkedList<>();
        for (int student : students) {
            queue.offer(student);
        }
        int sandwichIndex = 0;
        int unableToEat = 0;
        int maxMoves = students.length;

        while (!queue.isEmpty()) {
            int studentPreference = queue.peek();
            if (sandwiches[sandwichIndex] == studentPreference) {
                queue.poll();
                sandwichIndex++;
            } else {
                int preferenceSearchCount = 0;
                while (preferenceSearchCount < maxMoves && sandwiches[sandwichIndex] != studentPreference) {
                    sandwichIndex = (sandwichIndex + 1) % sandwiches.length;
                    preferenceSearchCount++;
                }

                if (preferenceSearchCount == maxMoves) {
                    unableToEat++;
                    queue.poll();
                } else {
                    queue.offer(queue.poll());
                    sandwichIndex = (sandwichIndex + 1) % sandwiches.length;
                }
            }

            if (unableToEat == students.length) {
                break;
            }
        }

        return unableToEat;
    }
}

