public class Solution {
    /**
     * Alice and Bob take turns playing a game, with Alice starting first.
     * There are n stones in a pile. On each player's turn, they can remove a stone
     * from the pile and receive points based on the stone's value. Alice and Bob may
     * value the stones differently. You are given two integer arrays of length n,
     * aliceValues and bobValues. Each aliceValues[i] and bobValues[i] represents
     * how Alice and Bob, respectively, value the <code>i<sup>th</sup></code> stone.
     * The winner is the person with the most points after all the stones are chosen.
     * If both players have the same amount of points, the game results in a draw.
     * Both players will play optimally. Both players know the other's values.
     * Determine the result of the game, and:
     * If Alice wins, return 1
     * If Bob wins, return -1
     * If the game results in a draw, return 0
     *
     * Example 1:
     * Input: aliceValues = [1,3], bobValues = [2,1]
     * Output: 1
     * Explanation: If Alice takes stone 1 (0-indexed) first, Alice will receive 3 points.
     * Bob can only choose stone 0, and will only receive 2 points. Alice wins.
     *
     * @param aliceValues An array of integers representing Alice's values for each stone.
     * @param bobValues   An array of integers representing Bob's values for each stone.
     * @return The result of the game: 1 if Alice wins, -1 if Bob wins, and 0 if it's a draw.
     */
    public int solve(int[] aliceValues, int[] bobValues) {
        int n = aliceValues.length;
        int[] combinedValues = new int[n];
        for (int i = 0; i < n; i++) {
            combinedValues[i] = aliceValues[i] - bobValues[i];
        }

        // Sort the stones based on the difference in values.
        // If the difference is positive, Alice prefers the stone more.
        // If the difference is negative, Bob prefers the stone more.
        Integer[] combinedValuesInteger = Arrays.stream(combinedValues).boxed().toArray(Integer[]::new);
        Arrays.sort(combinedValuesInteger);

        int aliceScore = 0;
        int bobScore = 0;

        for (int i = 0; i < n; i++) {
            if (i % 2 == 0) { // Alice's turn
                aliceScore += aliceValues[findIndexOfStone(aliceValues, combinedValuesInteger[i])];
            } else { // Bob's turn
                bobScore += bobValues[findIndexOfStone(bobValues, combinedValuesInteger[i])];
            }
        }

        if (aliceScore > bobScore) {
            return 1;
        } else if (bobScore > aliceScore) {
            return -1;
        } else {
            return 0;
        }
    }

    private int findIndexOfStone(int[] arr, int value) {
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] == value) {
                return i;
            }
        }
        return -1;
    }
}

