public class Solution {
    public int maximumRequests(int n, int[][] requests) {
        int maxRequests = 0;
        int[] balance = new int[n];
        for (int[] request : requests) {
            balance[request[0]]--;
            balance[request[1]]++;
        }

        return solve(n, requests, 0, balance, 0);
    }

    private int solve(int n, int[][] requests, int index, int[] balance, int currentRequests) {
        if (index == requests.length) {
            boolean valid = true;
            for (int b : balance) {
                if (b != 0) {
                    valid = false;
                    break;
                }
            }
            if (valid) {
                return currentRequests;
            } else {
                return 0;
            }
        }

        int maxRequests = 0;

        // Option 2: Exclude the current request
        maxRequests = Math.max(maxRequests, solve(n, requests, index + 1, balance, currentRequests));

        // Option 1: Include the current request
        int[] tempBalance = Arrays.copyOf(balance, n);
        tempBalance[requests[index][0]]++;
        tempBalance[requests[index][1]]--;


        maxRequests = Math.max(maxRequests, solve(n, requests, index + 1, tempBalance, currentRequests + 1));

        return maxRequests;
    }
}

