public class Solution {
    public List<Integer> busiestServers(int[] arrival, int[] load) {
        int k = arrival.length;
        int n = arrival.length;
        int[] serverLoad = new int[k];
        int[] serverCount = new int[k];

        for (int i = 0; i < n; i++) {
            int serverId = arrival[i] % k;
            int nextServerId = serverId;
            boolean assigned = false;

            while (!assigned) {
                if (serverLoad[nextServerId] == 0) {
                    serverLoad[nextServerId] = load[i];
                    serverCount[nextServerId]++;
                    assigned = true;
                } else {
                    nextServerId = (nextServerId + 1) % k;
                    if (nextServerId == serverId) {
                        // All servers are busy, drop the request
                        break;
                    }
                }
            }
        }

        int maxCount = 0;
        for (int count : serverCount) {
            maxCount = Math.max(maxCount, count);
        }

        List<Integer> busiestServers = new ArrayList<>();
        for (int i = 0; i < k; i++) {
            if (serverCount[i] == maxCount) {
                busiestServers.add(i);
            }
        }

        return busiestServers;
    }
}

