public class Solution {
    public int maxProfit(int[] inventory, int orders) {
        Arrays.sort(inventory);
        long profit = 0;
        int n = inventory.length;
        long MOD = 1000000007;

        int i = n - 1;
        long ballsSold = 0;

        while (orders > 0) {
            if (i < 0) {
                break;
