public class Solution {
    /**
     * You have n different types of stickers. Each sticker has a lowercase English word on it.
     * You would like to spell out the given string target by cutting individual letters from your collection of stickers and rearranging them.
     * You can use each sticker more than once if you want, and you have infinite quantities of each sticker.
     * Return the minimum number of stickers needed to spell out the target string. If the task is impossible, return -1.
     *
     * @param stickers The array of stickers.
     * @param target  The target string.
     * @return The minimum number of stickers needed to spell out the target string.
     */
    public int minStickers(String[] stickers, String target) {
        if (stickers == null || stickers.length == 0 || target == null || target.isEmpty()) {
            return -1;
        }

        Map<Character, Integer> targetCounts = new HashMap<>();
        for (char c : target.toCharArray()) {
            targetCounts.put(c, targetCounts.getOrDefault(c, 0) + 1);
        }

        int count = 0;
        while (true) {
            boolean allSatisfied = true;
            for (int i = 0; i < 26; i++) {
                if (targetCounts.getOrDefault((char) ('a' + i), 0) > 0) {
                    if (stickerCounts[i] == 0) {
                        allSatisfied = false;
                        break;
                    }
                }
            }

            if (allSatisfied) {
                break;
            }

            if (count > target.length()) {
                return -1;
            }

            int maxStickerIndex = -1;
            int maxContribution = 0;
            for (int i = 0; i < stickers.length; i++) {
                int contribution = 0;
                Map<Character, Integer> stickerCountsMap = new HashMap<>();
                for (char c : stickers[i].toCharArray()) {
                    stickerCountsMap.put(c, stickerCountsMap.getOrDefault(c, 0) + 1);
                }

                for (char c : target.toCharArray()) {
                    if (stickerCountsMap.containsKey(c) && stickerCountsMap.get(c) > 0 && targetCounts.get(c) > 0) {
                        contribution++;
                    }
                }

                if (contribution > maxContribution) {
                    maxContribution = contribution;
                    maxStickerIndex = i;
                }
            }

            if (maxStickerIndex == -1) {
                return -1;
            }

            Map<Character, Integer> stickerCountsMap = new HashMap<>();
            for (char c : stickers[maxStickerIndex].toCharArray()) {
                stickerCountsMap.put(c, stickerCountsMap.getOrDefault(c, 0) + 1);
            }

            for (char c : target.toCharArray()) {
                if (stickerCountsMap.containsKey(c) && stickerCountsMap.get(c) > 0 && targetCounts.get(c) > 0) {
                    targetCounts.put(c, targetCounts.get(c) - 1);
                }
            }
            count++;
        }

        return count;
    }

    private int[] stickerCounts = new int[26];
}

