class Solution {
    /**
     * Given a binary string s, return the number of non-empty substrings that have the same number of 0's and 1's, and all the 0's and all the 1's in these substrings are grouped consecutively.
     * Substrings that occur multiple times are counted the number of times they occur.
     *
     * @param s The binary string.
     * @return The number of non-empty substrings that have the same number of 0's and 1's, and all the 0's and all the 1's in these substrings are grouped consecutively.
     */
    public int countBinarySubstrings(String s) {
        int count = 0;
        for (int i = 0; i < s.length(); i++) {
            for (int j = i + 1; j <= s.length(); j++) {
                String sub = s.substring(i, j);
                if (isValid(sub)) {
                    count++;
                }
            }
        }
        return count;
    }

    private boolean isValid(String s) {
        if (s.length() % 2 != 0) {
            return false;
        }

        int zeros = 0;
        int ones = 0;
        for (char c : s.toCharArray()) {
            if (c == '0') {
                zeros++;
            } else {
                ones++;
            }
        }

        if (zeros != ones) {
            return false;
        }

        int i = 0;
        while (i < s.length() && s.charAt(i) == s.charAt(0)) {
            i++;
        }

        if (i == s.length()) {
            return true;
        }

        int j = i;
        while (j < s.length() && s.charAt(j) == s.charAt(i)) {
            j++;
        }

        return j == s.length();
    }
}

