public class Solution {
    public int[] maxSumOfThreeSubarrays(int[] nums, int k) {
        int n = nums.length;
        int[] sum = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            sum[i] = sum[i - 1] + nums[i - 1];
        }

        int[] left = new int[n];
        int best = 0;
        for (int i = k; i <= n; i++) {
            if (sum[i] - sum[i - k] > sum[best] - sum[best - k]) {
                best = i - k;
            }
            left[i - 1] = best;
        }

        int[] right = new int[n];
        best = 0;
        for (int i = n - k; i >= 0; i--) {
            if (sum[i + k] - sum[i] > sum[best + k] - sum[best]) {
                best = i;
            }
            right[i] = best;
        }

        int ans = -1;
        int max_sum = -1;
        for (int j = k; j <= n - 2 * k; j++) {
            int l = -1;
            if (j - k >= 0) {
                l = left[j - k];
            }
            int r = -1;
            if (j + k < n) {
                r = right[j + k];
            }

            if (l >= 0 && j >= k && r < n) {
                int current_sum = (sum[l + k] - sum[l]) + (sum[j + k] - sum[j]) + (sum[r + k] - sum[r]);
                if (current_sum > max_sum) {
                    max_sum = current_sum;
                    ans = l + j + r;
                } else if (current_sum == max_sum) {
                    int current_ans = l + j + r;
                    if (current_ans < ans) {
                        ans = current_ans;
                    }
                }
            }
        }

        if (ans == -1) {
            return new int[0];
        }

        if (k > 1 && k <= n) {
            int[] result = new int[3];
            result[0] = left[k - 1];
            result[1] = k;
            result[2] = right[n - k];
            return result;
        } else {
            return new int[0];
        }
    }
}

