import java.util.ArrayList;
import java.util.List;
import java.util.TreeSet;

public class Solution {
    public List<Integer> fallingSquares(int[][] positions) {
        List<Integer> ans = new ArrayList<>();
        TreeSet<Integer> heights = new TreeSet<>();
        heights.add(0);
        int maxHeight = 0;
        List<Integer> currentPositions = new ArrayList<>();

        for (int[] position : positions) {
            int left = position[0];
            int side = position[1];
            int right = left + side;

            int landingHeight = 0;
            for (Integer height : heights.descendingSet()) {
                if (height > 0) {
                    int squareLeft = currentPositions.get(heights.size() - 1 - height);
                    if (left < squareLeft + positions[heights.size() - 1 - height][1] && right > squareLeft) {
                        landingHeight = height;
                        break;
                    }
                }
            }

            int currentHeight = landingHeight + side;
            maxHeight = Math.max(maxHeight, currentHeight);
            heights.add(currentHeight);
            currentPositions.add(left);
            ans.add(maxHeight);
        }

        return ans;
    }
}

