// #Hard #String #Dynamic_Programming #2022_03_22_Time_24_ms_(76.35%)_Space_42_MB_(87.89%)
public class Solution {
    public int strangePrinter(String s) {
        int n = s.length();
        if (n == 0) return 0;

        int[][] dp = new int[n][n];

        for (int i = 0; i < n; i++) {
            dp[i][i] = 1;
        }

        for (int len = 2; len <= n; len++) {
            for (int i = 0; i <= n - len; i++) {
                int j = i + len - 1;
                dp[i][j] = j - i + 1;

                for (int k = i; k < j; k++) {
                    if (same(s, i, k) || same(s, k + 1, j)) {
                        dp[i][j] = Math.min(dp[i][j], dp[i][k] + dp[k + 1][j]);
                    } else {
                        dp[i][j] = Math.min(dp[i][j], dp[i][k] + dp[k + 1][j]);
                    }
                }
            }
        }

        return dp[0][n - 1];
    }

    private boolean same(String s, int i, int j) {
        char c = s.charAt(i);
        for (int k = i + 1; k <= j; k++) {
            if (s.charAt(k) != c) {
                return false;
            }
        }
        return true;
    }
}

