    private String serialize(TreeNode node) {
        if (node == null) {
            return "#";
        }
        return node.val + "," + serialize(node.left) + "," + serialize(node.right);
    }

    private void serializeAndCount(TreeNode root, Map<String, Integer> subtreeCounts, List<TreeNode> result) {
        if (root == null) {
            return;
        }

        String serializedSubtree = serialize(root);

        subtreeCounts.put(serializedSubtree, subtreeCounts.getOrDefault(serializedSubtree, 0) + 1);

        if (subtreeCounts.get(serializedSubtree) == 2) {
            result.add(root);
        }

        serializeAndCount(root.left, subtreeCounts, result);
        serializeAndCount(root.right, subtreeCounts, result);
    }
}

