public class Solution {
    public int flipLights(int n, int presses) {
        if (n == 0) {
            return 1;
        }

        if (presses == 0) {
            return 1;
        }

        long[] dp = new long[presses + 1];
        dp[0] = 1;

        for (int i = 1; i <= presses; i++) {
            dp[i] = 0;
            for (int j = 1; j <= 4; j++) {
                if (i >= j) {
                    dp[i] = (dp[i] + dp[i - j]) % 1000000007;
                }
            }
        }

        return (int) dp[presses];
    }
}

