public class Solution {
    public String solveEquation(String equation) {
        int xCoefficient = 0;
        int constant = 0;

        String[] parts = equation.split("=");
        if (parts.length != 2) {
            return "No solution";
        }

        String leftSide = parts[0];
        String rightSide = parts[1];

        int[] left = parseSide(leftSide);
        int[] right = parseSide(rightSide);

        xCoefficient = left[0] - right[0];
        constant = right[1] - left[1];

        if (xCoefficient == 0) {
            if (constant == 0) {
                return "Infinite solutions";
            } else {
                return "No solution";
            }
        }

        return "x=" + (constant / xCoefficient);
    }

    private int[] parseSide(String side) {
        int xCoefficient = 0;
        int constant = 0;

        String[] terms = side.split(Pattern.quote("+"));
        for (String term : terms) {
            term = term.trim();
            if (term.isEmpty()) continue;

            String[] subTerms = term.split(Pattern.quote("-"));
            if (subTerms.length == 1) {
                // Positive term
                if (term.contains("x")) {
                    String coeffStr = "";
                    if (term.startsWith("+")) {
                        coeffStr = term.substring(1);
                    } else if (term.startsWith("-")) {
                        coeffStr = term.substring(1);
                    } else {
                        coeffStr = term;
                    }
                    int coeff;
                    if (coeffStr.equals("x")) {
                        coeff = 1;
                    } else {
                        try {
                            coeff = Integer.parseInt(coeffStr);
                        } catch (NumberFormatException e) {
                            coeff = 1;
                        }
                    }
                    xCoefficient += coeff;
                } else {
                    try {
                        constant += Integer.parseInt(term);
                    } catch (NumberFormatException e) {
                        // Handle cases where the term is not a valid integer
                        constant += 0;
                    }
                }
            } else {
                // Negative term
                String firstTerm = subTerms[0].trim();
                for (int i = 1; i < subTerms.length; i++) {
                    String subTerm = subTerms[i].trim();
                    if (subTerm.isEmpty()) continue;

                    if (subTerm.contains("x")) {
                        String coeffStr = "";
                        if (subTerm.startsWith("+")) {
                            coeffStr = subTerm.substring(1);
                        } else if (subTerm.startsWith("-")) {
                            coeffStr = "-" + subTerm.substring(1);
                        } else {
                            coeffStr = subTerm;
                        }
                        int coeff;
                        if (coeffStr.equals("x")) {
                            coeff = -1;
                        } else {
                            try {
                                coeff = Integer.parseInt(coeffStr);
                            } catch (NumberFormatException e) {
                                coeff = -1;
                            }
                        }
                        xCoefficient -= coeff;
                    } else {
                        try {
                            constant -= Integer.parseInt(subTerm);
                        } catch (NumberFormatException e) {
                            constant -= 0;
                        }
                    }
                }
                if (!firstTerm.isEmpty()) {
                    if (firstTerm.contains("x")) {
                        String coeffStr = "";
                        if (firstTerm.startsWith("+")) {
                            coeffStr = firstTerm.substring(1);
                        } else if (firstTerm.startsWith("-")) {
                            coeffStr = "-" + firstTerm.substring(1);
                        } else {
                            coeffStr = firstTerm;
                        }
                        int coeff;
                        if (coeffStr.equals("x")) {
                            coeff = 1;
                        } else {
                            try {
                                coeff = Integer.parseInt(coeffStr);
                            } catch (NumberFormatException e) {
                                coeff = 1;
                            }
                        }
                        xCoefficient += coeff;
                    } else {
                        try {
                            constant += Integer.parseInt(firstTerm);
                        } catch (NumberFormatException e) {
                            constant += 0;
                        }
                    }
                }
            }
        }

        return new int[]{xCoefficient, constant};
    }
}

