public class Solution {
    public int minimumCost(int[] price, int[] needs, int[][] special) {
        int n = price.length;
        long[] dp = new long[n + 1];
        for (int i = 1; i <= n; i++) {
            dp[i] = Integer.MAX_VALUE;
        }

        for (int i = 0; i < n; i++) {
            dp[i + 1] = Math.min(dp[i + 1], (long)needs[i] * price[i]);
        }

        for (int[] offer : special) {
            int offerPrice = offer[n];
            for (int i = 0; i < n; i++) {
                int offerQuantity = offer[i];
                if (needs[i] >= offerQuantity) {
                    int remainingNeeds = needs[i] - offerQuantity;
                    long cost = (long)offerPrice;
                    if (remainingNeeds > 0) {
                        cost += (long)remainingNeeds * price[i];
                    }
                    dp[i + 1] = Math.min(dp[i + 1], cost);
                }
            }
        }

        long totalCost = 0;
        for (int i = 0; i < n; i++) {
            totalCost += dp[i + 1];
        }

        return (int)totalCost;
    }
}

