public class Solution {
    public List<List<String>> printTree(TreeNode root) {
        if (root == null) {
            return new ArrayList<>();
        }

        int height = getHeight(root);
        int m = height + 1;
        int n = (int) Math.pow(2, height) - 1;

        List<List<String>> res = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            res.add(new ArrayList<>());
            for (int j = 0; j < n; j++) {
                res.get(i).add("");
            }
        }

        printTreeHelper(root, 0, (n - 1) / 2, 0, m, n, res);

        return res;
    }

    private int getHeight(TreeNode root) {
        if (root == null) {
            return 0;
        }
        return 1 + Math.max(getHeight(root.left), getHeight(root.right));
    }

    private void printTreeHelper(TreeNode root, int row, int col, int level, int height, int width, List<List<String>> res) {
        if (root == null) {
            return;
        }

        res.get(row).set(col, String.valueOf(root.val));

        if (root.left != null) {
            printTreeHelper(root.left, row + 1, col - (int) Math.pow(2, level), level + 1, height, width, res);
        }

        if (root.right != null) {
            printTreeHelper(root.right, row + 1, col + (int) Math.pow(2, level), level + 1, height, width, res);
        }
    }
}

