public class Solution {
    public TreeNode addOneRow(TreeNode root, int val, int depth) {
        if (depth == 1) {
            TreeNode newRoot = new TreeNode(val);
            newRoot.left = root;
            return newRoot;
        }

        return addOneRowHelper(root, val, depth, 1);
    }

    private TreeNode addOneRowHelper(TreeNode root, int val, int depth, int currentDepth) {
        if (root == null) {
            return null;
        }

        if (currentDepth == depth - 1) {
            TreeNode newNode = new TreeNode(val);
            TreeNode tempLeft = root.left;
            root.left = newNode;
            newNode.left = tempLeft;
            return root;
        }

        root.right = addOneRowHelper(root.right, val, depth, currentDepth + 1);
        root.left = addOneRowHelper(root.left, val, depth, currentDepth + 1);

        return root;
    }
}

