import com_github_leetcode.TreeNode;
import java.util.LinkedList;
import java.util.Queue;

public class Solution {
    /**
     * Given the root of a binary tree, return the maximum width of the given tree.
     * The maximum width of a tree is the maximum width among all levels.
     * The width of one level is defined as the length between the end-nodes
     * (the leftmost and rightmost non-null nodes), where the null nodes between
     * the end-nodes are also counted into the length calculation.
     * It is guaranteed that the answer will in the range of 32-bit signed integer.
     *
     * @param root The root of the binary tree.
     * @return The maximum width of the given tree.
     */
    public int widthOfBinaryTree(TreeNode root) {
        if (root == null) {
            return 0;
        }

        int maxWidth = 0;
        Queue<Pair> queue = new LinkedList<>();
        queue.offer(new Pair(root, 0));

        while (!queue.isEmpty()) {
            int size = queue.size();
            int first = queue.peek().idx;
            int last = -1;

            for (int i = 0; i < size; i++) {
                Pair current = queue.poll();
                if (current.node != null) {
                    last = current.idx;

                    if (current.node.left != null) {
                        queue.offer(new Pair(current.node.left, 2 * current.idx + 1));
                    }

                    if (current.node.right != null) {
                        queue.offer(new Pair(current.node.right, 2 * current.idx + 2));
                    }
                }
            }

            maxWidth = Math.max(maxWidth, last - first + 1);
        }

        return maxWidth;
    }

    class Pair {
        TreeNode node;
        int idx;

        public Pair(TreeNode node, int idx) {
            this.node = node;
            this.idx = idx;
        }
    }
}

