        if (root == null) {
            return true;
        }

        return isBalancedHelper(root) != -1;
    }

    private int isBalancedHelper(TreeNode root) {
        if (root == null) {
            return 0;
        }

        int leftHeight = isBalancedHelper(root.left);
        if (leftHeight == -1) {
            return -1;
        }

        int rightHeight = isBalancedHelper(root.right);
        if (rightHeight == -1) {
            return -1;
