public class Solution {
    public Node copyRandomList(Node head) {
        if (head == null) {
            return null;
        }

        // Create a hash map to store the mapping between original nodes and copied nodes.
        java.util.HashMap<Node, Node> map = new java.util.HashMap<>();

        // First pass: Create copies of all nodes and store them in the hash map.
        Node current = head;
        while (current != null) {
            Node newNode = new Node(current.val);
            map.put(current, newNode);
            current = current.next;
        }

        // Second pass: Set the next and random pointers of the copied nodes.
        current = head;
        while (current != null) {
            Node newNode = map.get(current);
            newNode.next = (current.next != null) ? map.get(current.next) : null;
            newNode.random = (current.random != null) ? map.get(current.random) : null;
            current = current.next;
        }

        // Return the head of the copied list.
        return map.get(head);
    }
}

