public class Solution {
    public int maxNumberOfBalloons(String text) {
        Map<Character, Integer> charCounts = new HashMap<>();
        for (char c : text.toCharArray()) {
            charCounts.put(c, charCounts.getOrDefault(c, 0) + 1);
        }

        int bCount = charCounts.getOrDefault('b', 0);
        int aCount = charCounts.getOrDefault('a', 0);
        int lCount = charCounts.getOrDefault('l', 0);
        int oCount = charCounts.getOrDefault('o', 0);
        int nCount = charCounts.getOrDefault('n', 0);

        int minBalloons = Math.min(bCount, aCount);
        minBalloons = Math.min(minBalloons, lCount / 2);
        minBalloons = Math.min(minBalloons, oCount / 2);
        minBalloons = Math.min(minBalloons, nCount);

        return minBalloons;
    }
}

