public class Solution {
    public int movesToMakeZigzag(int[] nums) {
        int n = nums.length;
        int moves = 0;

        for (int i = 0; i < n; i++) {
            int left = (i > 0) ? nums[i - 1] : Integer.MIN_VALUE;
            int right = (i < n - 1) ? nums[i + 1] : Integer.MIN_VALUE;

            int largerNeighbor = Math.max(left, right);

            if (nums[i] >= largerNeighbor) {
                moves += nums[i] - largerNeighbor + 1;
            }
        }

        return moves;
    }
}

