public class Solution {
    public int maximumSum(int[] arr) {
        int n = arr.length;
        int maxSum = Integer.MIN_VALUE;

        for (int i = 0; i < n; i++) {
            int currentSum = 0;
            for (int j = i; j < n; j++) {
                currentSum += arr[j];

                // Option 1: No deletion
                maxSum = Math.max(maxSum, currentSum);

                // Option 2: Delete one element
                for (int k = i; k <= j; k++) {
                    int tempSum = currentSum - arr[k];
                    if (tempSum > maxSum) {
                        maxSum = tempSum;
                    }
                }
            }
        }

        return maxSum;
    }
}

