class Solution {
    public boolean canWin(TreeNode root, int n) {
        if (root == null) {
            return false;
        }

        for (int y = 1; y <= n; ++y) {
            if (y == root.val) continue;

            TreeNode[] board = new TreeNode[n + 1];
            for (int i = 1; i <= n; ++i) {
                board[i] = null;
            }

            TreeNode firstPlayerChoice = null;
            TreeNode secondPlayerChoice = null;

            // Player 1 chooses x
            firstPlayerChoice = findNode(root, root.val);
            if (firstPlayerChoice == null) continue;
            board[root.val] = firstPlayerChoice;

            // Player 2 chooses y
            boolean possible = false;
            for (int x = 1; x <= n; ++x) {
                if (x == root.val || x == y) continue;

                TreeNode player2Choice = findNode(root, y);
                if (player2Choice == null) continue;
                board[y] = player2Choice;
                possible = true;
                break;
            }

            if (!possible) continue;

            return true;
        }

        return false;
    }

    private TreeNode findNode(TreeNode root, int val) {
        if (root == null) {
            return null;
        }

        if (root.val == val) {
            return root;
        }

        TreeNode leftResult = findNode(root.left, val);
        if (leftResult != null) {
            return leftResult;
        }

        TreeNode rightResult = findNode(root.right, val);
        if (rightResult != null) {
            return rightResult;
        }

        return null;
    }
}

