        // Calculate the bitmask for each person
        int[] personBitmasks = new int[m];
        for (int i = 0; i < m; i++) {
            int bitmask = 0;
            for (String skill : people.get(i)) {
                bitmask |= skillToBit.get(skill);
            }
            personBitmasks[i] = bitmask;
        }

        // dp[i] is the smallest team to cover skills represented by i
        int[] dp = new int[1 << n];
        for (int i = 0; i < (1 << n); i++) {
            dp[i] = Integer.MAX_VALUE;
        }
        dp[0] = 0;

        for (int i = 1; i < (1 << n); i++) {
            for (int j = 0; j < m; j++) {
                int covered = personBitmasks[j];
                if ((covered & i) == i) {
                    if (dp[i ^ covered] != Integer.MAX_VALUE) {
                        dp[i] = Math.min(dp[i], dp[i ^ covered] + 1);
                    }
                }
            }
        }

        // Reconstruct the team
        List<Integer> team = new ArrayList<>();
        int mask = (1 << n) - 1;
        while (mask > 0) {
            int bestPerson = -1;
            int bestPersonMask = -1;
            for (int i = 0; i < m; i++) {
                if ((personBitmasks[i] & mask) == mask) {
                    if (bestPerson == -1 || personBitmasks[i] < bestPersonMask) {
                        bestPerson = i;
                        bestPersonMask = personBitmasks[i];
                    }
                }
            }
            team.add(bestPerson);
            mask ^= bestPersonMask;
        }

        int[] result = new int[team.size()];
        for (int i = 0; i < team.size(); i++) {
            result[i] = team.get(i);
        }

        return result;
    }
}

