import java.util.Arrays;

public class Solution {
    public int numPrimeArrangements(int n) {
        int primeCount = 0;
        for (int i = 2; i <= n; i++) {
            if (isPrime(i)) {
                primeCount++;
            }
        }

        long[] fact = new long[primeCount + 1];
        fact[0] = 1;
        for (int i = 1; i <= primeCount; i++) {
            fact[i] = (fact[i - 1] * i) % 1000000007;
        }

        return (int) fact[primeCount];
    }

    private boolean isPrime(int n) {
        if (n <= 1) {
            return false;
        }
        for (int i = 2; i * i <= n; i++) {
            if (n % i == 0) {
                return false;
            }
        }
        return true;
    }
}

