public class Solution {
    /**
     * Given an array of strings transaction where transactions[i] consists of comma-separated values
     * representing the name, time (in minutes), amount, and city of the transaction.
     * Return a list of transactions that are possibly invalid.
     * You may return the answer in any order.
     *
     * @param transactions The array of transaction strings.
     * @return A list of invalid transactions.
     */
    public List<String> findInvalidTransactions(List<String> transactions) {
        List<String> invalidTransactions = new ArrayList<>();
        Map<String, List<Transaction>> transactionsByNameAndCity = new HashMap<>();

        for (String transactionStr : transactions) {
            String[] parts = transactionStr.split(",");
            String name = parts[0];
            int time = Integer.parseInt(parts[1]);
            int amount = Integer.parseInt(parts[2]);
            String city = parts[3];

            Transaction transaction = new Transaction(name, time, amount, city);

            if (amount > 1000) {
                invalidTransactions.add(transactionStr);
            } else {
                transactionsByNameAndCity.computeIfAbsent(name, k -> new ArrayList<>()).add(transaction);
            }
        }

        for (List<Transaction> cityTransactions : transactionsByNameAndCity.values()) {
            for (int i = 0; i < cityTransactions.size(); i++) {
                for (int j = i + 1; j < cityTransactions.size(); j++) {
                    Transaction t1 = cityTransactions.get(i);
                    Transaction t2 = cityTransactions.get(j);
                    if (!t1.city.equals(t2.city) && Math.abs(t1.time - t2.time) <= 60) {
                        invalidTransactions.add(cityTransactions.get(i).toString());
                        invalidTransactions.add(cityTransactions.get(j).toString());
                    }
                }
            }
        }

        return invalidTransactions;
    }

    private static class Transaction {
        String name;
        int time;
        int amount;
        String city;

        public Transaction(String name, int time, int amount, String city) {
            this.name = name;
            this.time = time;
            this.amount = amount;
            this.city = city;
        }

        @Override
        public String toString() {
            return name + "," + time + "," + amount + "," + city;
        }
    }
}

