public class Solution {
    public List<Integer> pathInZigZagTree(int label) {
        List<Integer> path = new LinkedList<>();
        int row = 1;
        int totalNodes = 0;

        while (label > 0) {
            path.add(0, label);
            totalNodes = (row * (row + 1)) / 2;

            if (row % 2 == 1) {
                label = totalNodes - label + 1;
            } else {
                label = totalNodes - label;
            }
            row++;
        }

        return path;
    }
}

