        int[] boardDim = {6, 6};
        char[][] board = {
                {'a', 'b', 'c', 'd', 'e'},
                {'f', 'g', 'h', 'i', 'j'},
                {'k', 'l', 'm', 'n', 'o'},
                {'p', 'q', 'r', 's', 't'},
                {'u', 'v', 'w', 'x', 'y'},
                {'z'}
        };

        for (int i = 0; i < boardDim[0]; i++) {
            for (int j = 0; j < board[i].length; j++) {
                map.put(board[i][j], new int[]{i, j});
            }
        }

        StringBuilder path = new StringBuilder();
        int[] curr = {0, 0};

        for (char c : target.toCharArray()) {
            int[] next = map.get(c);

            int rowDiff = next[0] - curr[0];
            int colDiff = next[1] - curr[1];

            if (rowDiff > 0) {
                for (int i = 0; i < rowDiff; i++) {
                    path.append('D');
                }
            } else if (rowDiff < 0) {
                for (int i = 0; i < -rowDiff; i++) {
                    path.append('U');
                }
            }

            if (colDiff > 0) {
                for (int i = 0; i < colDiff; i++) {
                    path.append('R');
                }
            } else if (colDiff < 0) {
                for (int i = 0; i < -colDiff; i++) {
                    path.append('L');
                }
            }

            path.append('!');
            curr = next;
        }

        return path.toString();
