public class Solution {
    public int[] recoverArray(int n, int[] sums) {
        int[] ans = new int[n];
        List<Integer> nums = new ArrayList<>();

        if (n == 1) {
            ans[0] = sums[0];
            return ans;
        }

        nums.add(sums[0]);

        for (int i = 2; i <= n; i++) {
            int target = sums[i - 1];
            for (int j = 0; j < nums.size(); j++) {
                int currentSum = nums.get(j);
                if (currentSum < target && (target - currentSum) > 0) {
                    boolean found = false;
                    for (int k = 0; k < nums.size(); k++) {
                        if (nums.get(k) == (target - currentSum)) {
                            found = true;
                            break;
                        }
                    }
                    if (found) {
                        nums.add(target - currentSum);
                        break;
                    }
                }
            }
        }

        for (int i = 0; i < n; i++) {
            ans[i] = nums.get(i);
        }

        return ans;
    }
}

