public class Solution {
    public boolean canBeIncreasing(int[] nums) {
        int n = nums.length;
        int count = 0;
        int index = -1;

        for (int i = 1; i < n; i++) {
            if (nums[i - 1] >= nums[i]) {
                count++;
                index = i;
            }
        }

        if (count == 0) {
            return true;
        }

        if (count > 1) {
            return false;
        }

        if (index == 0) {
            return nums[2] > nums[1];
        }

        if (index == n - 1) {
            return nums[n - 2] < nums[n - 1];
        }

        int[] tempArray = new int[nums.length - 1];
        int j = 0;
        for (int i = 0; i < nums.length; i++) {
            if (i != index) {
                tempArray[j] = nums[i];
                j++;
            }
        }

        boolean isIncreasing = true;
        for (int i = 1; i < tempArray.length; i++) {
            if (tempArray[i - 1] >= tempArray[i]) {
                isIncreasing = false;
                break;
            }
        }
        return isIncreasing;
    }
}

