import java.util.Arrays;

public class Solution {
    public int[] rearrangeArray(int[] nums) {
        Arrays.sort(nums);
        int n = nums.length;
        int[] rearranged = new int[n];
        int left = 0;
        int right = n - 1;
        int index = 0;

        while (left <= right) {
            if (left == right) {
                rearranged[index++] = nums[left];
                break;
            }

            rearranged[index++] = nums[left];
            rearranged[index++] = nums[right];
            left++;
            right--;
        }

        for (int i = 1; i < n - 1; i++) {
            if ((double)(rearranged[i - 1] + rearranged[i + 1]) / 2 == rearranged[i]) {
                // If the condition is met, swap elements to find a valid arrangement
                int j = i + 1;
                while (j < n) {
                    if ((double)(rearranged[i - 1] + rearranged[j + 1]) / 2 != rearranged[j]) {
                        int temp = rearranged[i];
                        rearranged[i] = rearranged[j];
                        rearranged[j] = temp;
                        break;
                    }
                    j++;
                }
                if (j == n) {
                    // If no valid swap is found, return the original array
                    return nums;
                }
            }
        }

        return rearranged;
    }
}

