import java.util.HashSet;
import java.util.Set;

public class Solution {
    public long maxMatrixSum(int[][] matrix) {
        int n = matrix.length;
        long maxSum = Long.MIN_VALUE;

        for (int i = 0; i < (1 << (n * n)); i++) {
            long currentSum = 0;
            int[][] tempMatrix = new int[n][n];
            for (int row = 0; row < n; row++) {
                for (int col = 0; col < n; col++) {
                    tempMatrix[row][col] = matrix[row][col];
                }
            }

            Set<Integer> flipped = new HashSet<>();

            for (int j = 0; j < (n * n); j++) {
                if ((i & (1 << j)) != 0) {
                    int row = j / n;
                    int col = j % n;
                    int index = row * n + col;

                    if (!flipped.contains(index)) {
                        tempMatrix[row][col] *= -1;
                        flipped.add(index);

                        // Flip adjacent elements
                        if (row > 0 && !flipped.contains((row - 1) * n + col)) {
                            tempMatrix[row - 1][col] *= -1;
                            flipped.add((row - 1) * n + col);
                        }
                        if (col > 0 && !flipped.contains(row * n + (col - 1))) {
                            tempMatrix[row][col - 1] *= -1;
                            flipped.add(row * n + (col - 1));
                        }
                        if (row < n - 1 && !flipped.contains((row + 1) * n + col)) {
                            tempMatrix[row + 1][col] *= -1;
                            flipped.add((row + 1) * n + col);
                        }
                        if (col < n - 1 && !flipped.contains(row * n + (col + 1))) {
                            tempMatrix[row][col + 1] *= -1;
                            flipped.add(row * n + (col + 1));
                        }
                    }
                }
            }

            for (int row = 0; row < n; row++) {
                for (int col = 0; col < n; col++) {
                    currentSum += tempMatrix[row][col];
                }
            }

            maxSum = Math.max(maxSum, currentSum);
        }

        return maxSum;
    }
}

