public class Solution {
    public int[][] rotateGrid(int[][] grid, int k) {
        int m = grid.length;
        int n = grid[0].length;
        k = k % (m + n - 2);

        for (int rotation = 0; rotation < k; rotation++) {
            int[][] temp = new int[m][n];
            for (int i = 0; i < m; i++) {
                for (int j = 0; j < n; j++) {
                    int newRow = (i + 1) % m;
                    int newCol = (n + j - 1) % n;
                    temp[newRow][newCol] = grid[i][j];
                }
            }
            grid = temp;
        }

        return grid;
    }
}
